// =====================================================================
//  晨光羈絆：學園修行物語 — 遊戲本體（ES Module）
//  內容與單檔版 v1.1 完全相同；只加入「雲端擴充掛勾」HOOKS，讓存檔管理器可以：
//    1) 在每次本機存檔後排程雲端同步（afterSave）
//    2) 在重要事件發生時立即同步（emit：start / settle / reset / import / newsem / photo …）
//    3) 匯出時補回雲端照片、顯示雲端照片、加上雲端狀態說明
//  沒有設定雲端時，所有掛勾都是空的，行為與單檔版一致。
// =====================================================================

const HOOKS = {
  allowSave: null, afterSave: null, onEvent: null, photoURL: null, exportState: null,
  welcomeNote: null, welcomeExtra: null, settingsCard: null, saveNote: null,
};
function emit(name, detail) {
  if (HOOKS.onEvent) { try { HOOKS.onEvent(name, detail || {}); } catch (e) { console.warn('[cloud] onEvent hook failed', name, e); } }
}

