// =====================================================================
//  全家福卡通頭像（由全家福照片去背、卡通化）：full＝半身、face＝特寫、cut＝去背貼紙
//  圖檔放在 assets/images/toon/，用 import.meta.url 組出相對路徑，相容 GitHub Pages 子路徑
// =====================================================================
const TOON_BASE = new URL('../assets/images/toon/', import.meta.url).href;
const PHOTO_TOON = ['full', 'face', 'cut'].reduce((o, kind) => {
  o[kind] = {};
  ['hero', 'dad', 'mom', 'sis'].forEach((who) => { o[kind][who] = `${TOON_BASE}${kind}-${who}.${kind === 'cut' ? 'webp' : 'jpg'}`; });
  return o;
}, {});

// =====================================================================
//  美術：角色（3 表情 × 2 造型）與場景插圖（SVG）
// =====================================================================

let __uid = 0;
const uid = (p = 'u') => p + (++__uid);

const SKIN = '#f7d9c5', SKIN_S = '#eec2a8', BLUSH = '#f19f97';
const HAIR = { hero: '#1f1b1a', dad: '#211f21', mom: '#1e1817', sis: '#2b201c' };
// 臉型（依全家福：哥哥圓臉、爸爸方下巴、媽媽瓜子臉、妹妹圓潤）
const FACE = {
  hero: 'M54,90 C54,55 75,41 100,41 C125,41 146,55 146,90 C146,124 130,149 100,151 C70,149 54,124 54,90 Z',
  dad: 'M57,88 C57,55 77,41 100,41 C123,41 143,55 143,88 C143,121 132,146 100,149 C68,146 57,121 57,88 Z',
  mom: 'M58,90 C58,56 77,43 100,43 C123,43 142,56 142,90 C142,120 126,143 100,146 C74,143 58,120 58,90 Z',
  sis: 'M56,92 C56,57 76,43 100,43 C124,43 144,57 144,92 C144,124 127,146 100,148 C73,146 56,124 56,92 Z',
};
const TORSO = 'M18,240 C22,204 52,180 100,178 C148,180 178,204 182,240 Z';

function avatarInner(who, expr = 'smile', outfit = 'casual') {
  const id = uid('av');
  const hc = HAIR[who];
  let s = `<defs><clipPath id="${id}t"><path d="${TORSO}"/></clipPath></defs>`;
  // 後方長髮
  if (who === 'mom') s += `<path d="M48,98 C44,46 78,28 100,28 C124,28 158,46 152,98 C156,140 162,196 160,240 L40,240 C38,196 44,140 48,98 Z" fill="${hc}"/>`;
  if (who === 'sis') s += `<path d="M52,98 C48,52 78,36 100,36 C122,36 152,52 148,98 C150,120 148,140 142,158 L58,158 C52,140 50,120 52,98 Z" fill="${hc}"/>`;
  s += torso(who, outfit, id);
  // 脖子
  s += `<path d="M86,134 L86,174 Q100,186 114,174 L114,134 Z" fill="${SKIN}"/>`;
  s += `<path d="M86,148 Q100,164 114,148 L114,138 Q100,152 86,138 Z" fill="${SKIN_S}" opacity=".7"/>`;
  s += collar(who, outfit, id);
  // 披在肩上的長髮
  if (who === 'mom') s += `<path d="M52,118 C50,160 54,200 60,236 L76,236 C70,200 66,160 66,120 Z" fill="${hc}"/><path d="M148,118 C150,160 146,200 140,236 L124,236 C130,200 134,160 134,120 Z" fill="${hc}"/>`;

  // 耳朵與臉
  s += `<ellipse cx="56" cy="100" rx="7" ry="10" fill="${SKIN}"/><ellipse cx="144" cy="100" rx="7" ry="10" fill="${SKIN}"/>`;
  s += `<path d="${FACE[who]}" fill="${SKIN}"/>`;
  s += face(who, expr);
  s += frontHair(who, hc);
  if (who === 'dad') s += glasses();
  return s;
}

function torso(who, outfit, id) {
  const formal = outfit === 'formal';
  const main = formal
    ? { hero: '#24272d', dad: '#1e2c4c', mom: '#f3ebdc', sis: '#efe3cb' }[who]
    : { hero: '#5f81a7', dad: '#a9c2dc', mom: '#dfb2a9', sis: '#f2c48e' }[who];
  let s = `<path d="${TORSO}" fill="${main}"/>`;
  s += `<path d="M140,186 C160,196 176,214 182,240 L152,240 C152,220 148,200 140,186 Z" fill="#000" opacity=".07"/>`;
  if (formal && who === 'sis') {
    let st = '';
    for (let x = 24; x < 182; x += 9) st += `<line x1="${x}" y1="176" x2="${x}" y2="240" stroke="#d8c5a0" stroke-width="1.6"/>`;
    s += `<g clip-path="url(#${id}t)">${st}</g>`;
    s += `<rect x="26" y="226" width="148" height="12" fill="#1c1c1c"/><rect x="92" y="223" width="16" height="17" rx="2" fill="none" stroke="#b9a273" stroke-width="2.5"/>`;
  }
  if (formal && who === 'mom') {
    s += `<path d="M60,214 C70,206 80,206 86,216" stroke="#ddd0b8" stroke-width="2" fill="none"/><path d="M140,214 C130,206 120,206 114,216" stroke="#ddd0b8" stroke-width="2" fill="none"/>`;
  }
  if (!formal && who === 'mom') {
    s += `<path d="M84,177 L100,240 L82,240 L70,190 Z" fill="#000" opacity=".05"/>`;
  }
  return s;
}

function collar(who, outfit, id) {
  let s = '';
  if (outfit === 'formal' && (who === 'hero' || who === 'dad')) {
    const lap = who === 'hero' ? '#16181d' : '#15223f';
    s += `<path d="M84,176 L100,216 L116,176 Z" fill="#fbfbfb"/>`;
    s += `<path d="M84,176 L100,216 L80,206 L66,188 Z" fill="${lap}"/><path d="M116,176 L100,216 L120,206 L134,188 Z" fill="${lap}"/>`;
    s += `<path d="M86,176 L97,186 L92,191 Z" fill="#ffffff" stroke="#d9d9d9" stroke-width="1"/><path d="M114,176 L103,186 L108,191 Z" fill="#ffffff" stroke="#d9d9d9" stroke-width="1"/>`;
    const tc = who === 'hero' ? '#141414' : '#7b1f2e', sc = who === 'hero' ? '#e8e8e8' : '#c45d6e';
    const tie = 'M95,186 L105,186 L107,193 L103,232 L100,238 L97,232 L93,193 Z';
    let ln = '';
    for (let y = 182; y < 246; y += 7) ln += `<line x1="88" y1="${y + 6}" x2="112" y2="${y - 4}" stroke="${sc}" stroke-width="2.2"/>`;
    s += `<defs><clipPath id="${id}k"><path d="${tie}"/></clipPath></defs><path d="${tie}" fill="${tc}"/><g clip-path="url(#${id}k)">${ln}</g>`;
    s += `<path d="M94,178 L106,178 L105,187 L95,187 Z" fill="${tc}"/>`;
  } else if (outfit === 'formal' && who === 'mom') {
    const st = 'fill="#f7f0e3" stroke="#d5c6aa" stroke-width="1.5"';
    s += `<path d="M100,184 C88,171 75,175 79,188 C83,198 96,192 100,186 Z" ${st}/><path d="M100,184 C112,171 125,175 121,188 C117,198 104,192 100,186 Z" ${st}/>`;
    s += `<path d="M98,188 L89,215 L97,211 Z" ${st}/><path d="M102,188 L111,215 L103,211 Z" ${st}/>`;
    s += `<ellipse cx="100" cy="186" rx="5" ry="4.5" fill="#efe5d2" stroke="#d5c6aa" stroke-width="1.5"/>`;
  } else if (outfit === 'formal' && who === 'sis') {
    s += `<path d="M84,176 L100,194 L116,176 L122,186 L100,200 L78,186 Z" fill="#f8f1e3" stroke="#d8c5a0" stroke-width="1.2"/>`;
    s += `<line x1="100" y1="200" x2="100" y2="224" stroke="#d8c5a0" stroke-width="1.5"/><circle cx="100" cy="208" r="1.8" fill="#cbb48b"/><circle cx="100" cy="218" r="1.8" fill="#cbb48b"/>`;
  } else if (who === 'hero') {
    s += `<path d="M72,178 C78,200 122,200 128,178 C120,190 80,190 72,178 Z" fill="#4c6c90"/>`;
    s += `<path d="M93,192 L91,218" stroke="#eef2f7" stroke-width="2.4" stroke-linecap="round"/><path d="M107,192 L109,218" stroke="#eef2f7" stroke-width="2.4" stroke-linecap="round"/>`;
  } else if (who === 'dad') {
    s += `<path d="M86,176 L100,192 L94,201 L79,186 Z" fill="#c6d8eb"/><path d="M114,176 L100,192 L106,201 L121,186 Z" fill="#c6d8eb"/>`;
    s += `<line x1="100" y1="192" x2="100" y2="240" stroke="#8fa9c6" stroke-width="1.5"/><circle cx="100" cy="207" r="1.8" fill="#eef3f9"/><circle cx="100" cy="223" r="1.8" fill="#eef3f9"/>`;
  } else if (who === 'mom') {
    s += `<path d="M84,177 L100,212 L116,177 Z" fill="#fbf6ef"/>`;
    s += `<path d="M84,177 L100,212" stroke="#c99a90" stroke-width="2.2"/><path d="M116,177 L100,212" stroke="#c99a90" stroke-width="2.2"/>`;
    s += `<circle cx="100" cy="222" r="2" fill="#c99a90"/><circle cx="100" cy="233" r="2" fill="#c99a90"/>`;
  } else if (who === 'sis') {
    s += `<path d="M80,178 Q100,194 120,178" stroke="#e0a964" stroke-width="6" fill="none" stroke-linecap="round"/>`;
    s += `<path d="M124,208 c-3,-4 -9,-2 -7,3 l7,6 l7,-6 c2,-5 -4,-7 -7,-3 Z" fill="#e57d8d"/>`;
  }
  return s;
}

function face(who, expr) {
  const ink = '#2b1d18', brow = '#3a2a24', lip = '#b65a52';
  const ey = 99, lx = 81, rx = 119;
  const k = who === 'sis' ? 1.16 : who === 'mom' ? 1.05 : 1;
  const bw = who === 'dad' ? 4 : 3.2;
  const B = (d) => `<path d="${d}" stroke="${brow}" stroke-width="${bw}" fill="none" stroke-linecap="round"/>`;
  let s = '';
  if (expr === 'concern') s += B('M70,86 L91,80') + B('M130,86 L109,80');
  else if (expr === 'happy') s += B('M70,83 Q80,76 91,81') + B('M130,83 Q120,76 109,81');
  else s += B('M70,85 Q80,80 91,83') + B('M130,85 Q120,80 109,83');
  if (expr === 'happy') {
    s += `<path d="M73,${ey + 2} Q81,${ey - 7} 89,${ey + 2}" stroke="${ink}" stroke-width="3.4" fill="none" stroke-linecap="round"/>`;
    s += `<path d="M111,${ey + 2} Q119,${ey - 7} 127,${ey + 2}" stroke="${ink}" stroke-width="3.4" fill="none" stroke-linecap="round"/>`;
  } else {
    const dy = expr === 'concern' ? 1 : 0, rX = 5 * k, rY = 6.4 * k;
    s += `<ellipse cx="${lx}" cy="${ey + dy}" rx="${rX}" ry="${rY}" fill="${ink}"/><ellipse cx="${rx}" cy="${ey + dy}" rx="${rX}" ry="${rY}" fill="${ink}"/>`;
    s += `<circle cx="${lx + 1.8}" cy="${ey + dy - 2.4}" r="${1.8 * k}" fill="#fff"/><circle cx="${rx + 1.8}" cy="${ey + dy - 2.4}" r="${1.8 * k}" fill="#fff"/>`;
    if (who === 'mom' || who === 'sis') {
      s += `<path d="M${lx - 8},${ey - 4} Q${lx},${ey - 11} ${lx + 8},${ey - 5}" stroke="${ink}" stroke-width="2" fill="none" stroke-linecap="round"/>`;
      s += `<path d="M${rx - 8},${ey - 5} Q${rx},${ey - 11} ${rx + 8},${ey - 4}" stroke="${ink}" stroke-width="2" fill="none" stroke-linecap="round"/>`;
    }
  }
  s += `<path d="M100,107 Q97,113 101,115" stroke="#d6a189" stroke-width="2" fill="none" stroke-linecap="round"/>`;
  if (expr === 'happy') s += `<path d="M88,121 Q100,139 112,121 Z" fill="#a8504b"/><path d="M93,129 Q100,135 107,129 Q100,132 93,129 Z" fill="#e8847e"/>`;
  else if (expr === 'concern') s += `<path d="M92,127 Q100,123 108,127" stroke="${lip}" stroke-width="3" fill="none" stroke-linecap="round"/>`;
  else s += `<path d="M90,122 Q100,130 110,122" stroke="${lip}" stroke-width="3" fill="none" stroke-linecap="round"/>`;
  const bo = expr === 'happy' ? 0.55 : 0.38;
  s += `<ellipse cx="71" cy="114" rx="8" ry="4.5" fill="${BLUSH}" opacity="${bo}"/><ellipse cx="129" cy="114" rx="8" ry="4.5" fill="${BLUSH}" opacity="${bo}"/>`;
  return s;
}

function frontHair(who, hc) {
  // 哥哥：兩側推短的平頭，頭頂稍長、瀏海往上抓
  if (who === 'hero') return `<path d="M55,94 C51,56 74,35 102,35 C130,35 150,55 145,94 C143,84 140,77 136,71 C126,64 112,61 100,61 C87,61 74,64 66,70 C61,77 57,85 55,94 Z" fill="${hc}"/>`
    + `<path d="M68,68 C76,52 96,44 120,48 C110,53 102,58 98,66 C88,61 78,62 68,68 Z" fill="${hc}"/>`
    + `<path d="M84,44 C96,39 112,39 124,45" stroke="#3d3632" stroke-width="2.2" fill="none" stroke-linecap="round"/>`
    + `<path d="M58,90 C59,84 60,80 62,77" stroke="#4a423e" stroke-width="1.6" fill="none" opacity=".7"/><path d="M142,90 C141,84 140,80 138,77" stroke="#4a423e" stroke-width="1.6" fill="none" opacity=".7"/>`;
  // 爸爸：俐落的黑色短髮、旁分
  if (who === 'dad') return `<path d="M55,94 C52,56 76,38 102,38 C130,38 150,56 145,94 C142,80 136,68 124,62 C110,60 94,60 82,64 C70,70 60,80 55,94 Z" fill="${hc}"/>`
    + `<path d="M82,64 C88,54 98,48 112,46" stroke="#4a4648" stroke-width="2" fill="none"/>`;
  // 媽媽：黑色直長髮、旁分，大片側瀏海往左撥
  if (who === 'mom') return `<path d="M120,40 C96,37 66,50 58,84 C56,102 55,120 54,140 C60,118 66,98 77,84 C89,70 104,61 120,53 Z" fill="${hc}"/>`
    + `<path d="M120,40 C134,42 146,58 146,94 L148,140 C142,118 138,98 132,84 C128,72 124,61 120,53 Z" fill="${hc}"/>`
    + `<path d="M116,44 C100,46 84,54 74,68" stroke="#3a302d" stroke-width="1.6" fill="none" opacity=".75"/>`;
  // 妹妹：中分、往後綁、露出額頭，耳前留幾縷碎髮
  return `<path d="M100,40 C80,40 62,52 58,80 C57,90 57,98 58,104 C62,88 70,74 84,64 C92,58 97,52 100,46 Z" fill="${hc}"/>`
    + `<path d="M100,40 C120,40 138,52 142,80 C143,90 143,98 142,104 C138,88 130,74 116,64 C108,58 103,52 100,46 Z" fill="${hc}"/>`
    + `<path d="M58,96 C55,118 57,140 65,160 L70,158 C64,138 62,118 63,98 Z" fill="${hc}"/><path d="M142,96 C145,118 143,140 135,160 L130,158 C136,138 138,118 137,98 Z" fill="${hc}"/>`
    + `<path d="M90,44 C94,42 98,41 100,41" stroke="#5b463c" stroke-width="1.6" fill="none" opacity=".8"/>`;
}

function glasses() {
  const st = 'fill="none" stroke="#1b1b1b" stroke-width="2.6"';
  return `<rect x="66" y="90" width="29" height="18" rx="3.5" ${st}/><rect x="105" y="90" width="29" height="18" rx="3.5" ${st}/>`
    + `<path d="M95,96 Q100,93 105,96" ${st}/><path d="M66,95 L57,93" ${st}/><path d="M134,95 L143,93" ${st}/>`
    + `<path d="M70,94 L75,92" stroke="#fff" stroke-width="2" opacity=".7"/><path d="M109,94 L114,92" stroke="#fff" stroke-width="2" opacity=".7"/>`;
}

function avatarSVG(who, expr = 'smile', outfit = 'casual', cls = '') {
  return `<svg class="av ${cls}" viewBox="0 0 200 240" aria-hidden="true">${avatarInner(who, expr, outfit)}</svg>`;
}

// 頭像（若使用者上傳了照片，優先使用照片）
// 全家福卡通頭像：啟動時轉成 blob 網址，避免每個頭像都塞一大串 base64 進 DOM
const TOON_URL = { full: {}, face: {}, cut: {} };
function initToon() {
  if (typeof PHOTO_TOON === 'undefined') return;
  ['full', 'face', 'cut'].forEach((kind) => Object.assign(TOON_URL[kind], PHOTO_TOON[kind] || {}));
}
const useToon = () => !(S && S.profile && S.profile.avatarStyle === 'svg');

// 玩家上傳的照片：先看存檔內的 data URL（舊版／尚未上傳），再問雲端照片快取
function photoOf(who) {
  const p = S && S.profile;
  if (!p) return null;
  if (p.photos && p.photos[who]) return p.photos[who];
  if (HOOKS.photoURL) { try { return HOOKS.photoURL(who) || null; } catch (e) { return null; } }
  return null;
}

function portrait(who, expr = 'smile', outfit = 'casual', cls = '') {
  const ph = S && S.profile && S.profile.usePhotos && photoOf(who);
  if (ph) return `<img class="av photo ${cls}" src="${ph}" alt="">`;
  if (useToon()) {
    const kind = /\b(tiny|mini)\b/.test(cls) ? 'face' : /\bhero-big\b/.test(cls) ? 'cut' : 'full';
    const src = TOON_URL[kind][who] || TOON_URL.full[who];
    if (src) return `<img class="av photo toon ${kind} ${cls}" src="${src}" alt="">`;
  }
  return avatarSVG(who, expr, outfit, cls);
}

function actor(a) {
  const [who, expr, outfit, x, y, h] = a;
  const w = h * 200 / 240;
  return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="0 0 200 240" overflow="visible">${avatarInner(who, expr, outfit)}</svg>`;
}

function wrapLines(text, n) {
  const out = [];
  let cur = '';
  for (const ch of text) {
    cur += ch;
    if (cur.length >= n) { out.push(cur); cur = ''; }
  }
  if (cur) out.push(cur);
  return out;
}

// ---------- 場景 ----------
function clockHands(cx, cy, h) {
  const a = (h % 12) * 30 * Math.PI / 180;
  const hx = cx + 12 * Math.sin(a), hy = cy - 12 * Math.cos(a);
  return `<line x1="${cx}" y1="${cy}" x2="${hx.toFixed(1)}" y2="${hy.toFixed(1)}" stroke="#5a4636" stroke-width="3.4" stroke-linecap="round"/>`
    + `<line x1="${cx}" y1="${cy}" x2="${cx}" y2="${cy - 18}" stroke="#5a4636" stroke-width="2.4" stroke-linecap="round"/>`;
}

function grad(id, a, b, vertical = true) {
  return `<linearGradient id="${id}" x1="0" y1="0" x2="${vertical ? 0 : 1}" y2="${vertical ? 1 : 0}"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient>`;
}

