// 迷你課表（兄妹交換課表的手機畫面）
function miniTimetable(list, x0, y0, w, h, color, mark) {
  const cw = w / 5;
  let g = `<rect x="${x0}" y="${y0}" width="${w}" height="${h}" rx="6" fill="#fffdf9"/>`;
  for (let i = 1; i < 5; i++) g += `<line x1="${x0 + i * cw}" y1="${y0}" x2="${x0 + i * cw}" y2="${y0 + h}" stroke="#efe4d4" stroke-width="1"/>`;
  [10, 12, 14, 16].forEach((hh) => { const y = y0 + (hh - 8) / 10 * h; g += `<line x1="${x0}" y1="${y}" x2="${x0 + w}" y2="${y}" stroke="#f3eadc" stroke-width="1"/>`; });
  (list || []).forEach((c) => {
    const d = Number(c.day);
    if (d < 1 || d > 5) return;
    const a = Math.max(480, tmin(c.start)), b = Math.min(1080, tmin(c.end));
    if (b <= a) return;
    const y = y0 + (a - 480) / 600 * h, hh = Math.max(4, (b - a) / 600 * h - 1.5);
    const early = tmin(c.start) < 540 && (d === 3 || d === 4) && mark;
    g += `<rect x="${(x0 + (d - 1) * cw + 2).toFixed(1)}" y="${y.toFixed(1)}" width="${(cw - 4).toFixed(1)}" height="${hh.toFixed(1)}" rx="3" fill="${color}" opacity="${c.parity === 'odd' ? 0.55 : 0.9}"/>`;
    if (early) g += `<text x="${(x0 + (d - 0.5) * cw).toFixed(1)}" y="${(y + 11).toFixed(1)}" font-size="11" text-anchor="middle">⚡</text>`;
  });
  return g;
}

