// =====================================================================
//  引擎：工具、日期、存檔、規則計算、每日結算、挑戰與活動
// =====================================================================

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const r1 = (v) => Math.round(v * 10) / 10;
const pad = (n) => String(n).padStart(2, '0');
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];
const signed = (v) => (v > 0 ? '+' : v < 0 ? '−' : '±') + Math.abs(r1(v));

const D = {
  ms: (s) => { const [y, m, d] = s.split('-').map(Number); return Date.UTC(y, m - 1, d); },
  str: (ms) => { const d = new Date(ms); return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`; },
  add: (s, n) => D.str(D.ms(s) + n * 86400000),
  diff: (a, b) => Math.round((D.ms(b) - D.ms(a)) / 86400000),
  wd: (s) => { const w = new Date(D.ms(s)).getUTCDay(); return w === 0 ? 7 : w; },
  monday: (s) => D.add(s, 1 - D.wd(s)),
  month: (s) => s.slice(0, 7),
  md: (s) => { const [, m, d] = s.split('-').map(Number); return `${m}/${d}`; },
  label: (s) => `${D.md(s)}（${'一二三四五六日'[D.wd(s) - 1]}）`,
  wname: (n) => '週' + '一二三四五六日'[n - 1],
};
const tmin = (t) => { const [h, m] = String(t || '0:0').split(':').map(Number); return h * 60 + (m || 0); };
const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);

const QP = new URLSearchParams(location.search);
function today() {
  const o = QP.get('date');
  if (isDate(o)) return o;
  const n = new Date();
  return `${n.getFullYear()}-${pad(n.getMonth() + 1)}-${pad(n.getDate())}`;
}

// ---------------------------------------------------------------------
//  存檔
// ---------------------------------------------------------------------
function nowMinutes() {
  const o = QP.get('time');
  if (/^\d{1,2}:\d{2}$/.test(o || '')) return tmin(o);
  const n = new Date();
  return n.getHours() * 60 + n.getMinutes();
}
function hashStr(t) { let h = 2166136261; for (const ch of String(t)) { h ^= ch.codePointAt(0); h = Math.imul(h, 16777619); } return h >>> 0; }
const dpick = (arr, seed) => (arr && arr.length ? arr[hashStr(seed) % arr.length] : '');
const shortName = (c) => c.short || String(c.name || '').replace(/[（(].*?[)）]/g, '').slice(0, 5);

const SAVE_KEY = 'chenguang-bond-save-v1' + (QP.get('slot') ? '-' + QP.get('slot') : '');
let S = null;
let memorySave = null;
let storageOK = true;

function defaultState() {
  return {
    version: 2, started: false, createdAt: null, settledThrough: null,
    profile: { hero: '振嘉', names: { mom: '媽媽', dad: '爸爸', sis: '妹妹' }, photos: {}, usePhotos: true, voice: true, avatarStyle: 'toon', sisSchool: SIS_INFO.school + ' ' + SIS_INFO.dept },
    settings: { semStart: '2026-09-14', weeks: 18, midWeek: 9, bedtime: '23:00', wake: '06:45', holidays: DEFAULT_HOLIDAYS.map((h) => ({ ...h })), weakIds: DEFAULT_WEAK.slice() },
    schedule: DEFAULT_SCHEDULE.map((x) => ({ ...x })),
    sisSchedule: SIS_SCHEDULE.map((x) => ({ ...x })),
    player: { exp: 0, level: 1, sp: 0, skills: {}, disc: 30, grit: 30, knowPts: 0, knowBonus: 0 },
    bonds: { mom: { aff: 20, lv: 0 }, dad: { aff: 15, lv: 0 }, sis: { aff: 25, lv: 0 } },
    items: { supply: 0, medal: 0, candy: 0 },
    grants: { week: '', month: '' },
    days: {},
    streak: { attend: 0, wake: 0, bad: 0, noMiss: 0, prevAbsent: false, prevWakeBad: false },
    counters: { early: 0, events: 0, companion: 0, remedies: 0, boring: 0, weakRun: 0, weakDone: 0, holidayWins: 0, maxAttend: 0, sync: 0 },
    weekly: {}, monthly: {}, holidayEv: {}, midEv: {}, sibWeekly: {}, syncDays: [],
    tasks: { pe: { done: false, hidden: false } },
    shares: [], album: {}, achievements: {}, collection: {},
    recentEvents: [], queue: [], log: [], ending: null, history: [],
    flags: { resonance: false, dad4: false, sis4: false, careLast: '' },
  };
}

function migrate(s) {
  const d = defaultState();
  const merged = Object.assign(d, s);
  for (const k of ['profile', 'settings', 'player', 'items', 'grants', 'streak', 'counters', 'flags']) merged[k] = Object.assign(defaultState()[k], s[k] || {});
  merged.profile.names = Object.assign(defaultState().profile.names, (s.profile || {}).names || {});
  merged.profile.photos = Object.assign({}, (s.profile || {}).photos || {});
  merged.bonds = Object.assign(defaultState().bonds, s.bonds || {});
  merged.tasks = Object.assign(defaultState().tasks, s.tasks || {});
  if (!Array.isArray(merged.sisSchedule)) merged.sisSchedule = SIS_SCHEDULE.map((x) => ({ ...x }));
  if (!Array.isArray(merged.syncDays)) merged.syncDays = [];
  if ((s.version || 1) < 2) upgradeV2(merged);
  return merged;
}

// v2：這學期不再上體育 → 從課表與紀錄中整個移除；探索永續改為整學期；加入妹妹的課表與劇情
function upgradeV2(m) {
  const isPE = (c) => c && (c.id === 's7' || /體育/.test(c.name || ''));
  const peIds = new Set((m.schedule || []).filter(isPE).map((c) => c.id));
  peIds.add('s7');
  m.schedule = (m.schedule || []).filter((c) => !isPE(c));
  m.settings.weakIds = (m.settings.weakIds || []).filter((x) => !peIds.has(x));
  m.schedule.forEach((c) => { if (c.id === 's4' && (c.note === OLD_S4_NOTE || !c.note)) c.note = '整學期課程'; });
  m.schedule.forEach((c) => { if (!c.short && DEFAULT_SHORT[c.id + '|' + c.name]) c.short = DEFAULT_SHORT[c.id + '|' + c.name]; });
  Object.values(m.days || {}).forEach((day) => {
    if (day.reports) peIds.forEach((id) => { delete day.reports[id]; });
    if (day.summary && Array.isArray(day.summary.items)) day.summary.items = day.summary.items.filter((i) => !peIds.has(i.id) && !/體育/.test(i.name || ''));
  });
  if (m.started && !(m.album && m.album.sisPlan)) {
    m.queue = m.queue || [];
    m.queue.push({ type: 'story', id: 'sisPlan' });
    m.album = m.album || {};
    m.album.sisPlan = today();
    if (!m.collection.plan) m.collection.plan = today();
  }
  m.version = 2;
}

function load() {
  let raw = null;
  try { raw = localStorage.getItem(SAVE_KEY); } catch (e) { storageOK = false; raw = memorySave; }
  if (raw) {
    try { S = migrate(JSON.parse(raw)); return; } catch (e) { console.warn('存檔讀取失敗', e); }
  }
  S = defaultState();
}

function save(reason) {
  // 雲端擴充：遊戲已在同一個瀏覽器的另一個分頁進行時，這個分頁不寫入存檔（避免舊畫面蓋掉新進度）
  if (HOOKS.allowSave && !HOOKS.allowSave()) return;
  const raw = JSON.stringify(S);
  try { localStorage.setItem(SAVE_KEY, raw); storageOK = true; } catch (e) { storageOK = false; memorySave = raw; }
  // 雲端擴充：每次本機存檔後通知存檔管理器（只排程同步，不改變遊戲狀態）
  if (HOOKS.afterSave) { try { HOOKS.afterSave(reason || 'save'); } catch (e) { console.warn('[cloud] afterSave hook failed', e); } }
}

// 好感與屬性越高，提升越慢（遞減）
const DAMP_AFF = (a) => Math.max(0.08, 0.7 * (1 - a / 100));
const DAMP_ATTR = (x) => Math.max(0.1, 1 - x / 105);
function effAff(m, v) { return v > 0 ? r1(v * DAMP_AFF(S.bonds[m].aff)) : v; }
function addAff(m, v) { const e = effAff(m, v); S.bonds[m].aff = clamp(r1(S.bonds[m].aff + e), 0, 100); return e; }
function effAttr(k, v) { return v > 0 ? r1(v * DAMP_ATTR(S.player[k])) : r1(v); }
function addAttr(k, v) { const e = effAttr(k, v); S.player[k] = clamp(r1(S.player[k] + e), 0, 100); return e; }
const affShow = (a) => Math.floor(a + 1e-9);
let CTX_DATE = null;
const nowDate = () => CTX_DATE || playDate() || today();

function logEv(text, d) {
  S.log.unshift({ d: d || nowDate(), t: text });
  if (S.log.length > 250) S.log.length = 250;
}

// ---------------------------------------------------------------------
//  學期、課表、假日
// ---------------------------------------------------------------------
const semEnd = () => D.add(S.settings.semStart, S.settings.weeks * 7 - 1);
const semWeek = (d) => Math.floor(D.diff(S.settings.semStart, d) / 7) + 1;
const inSem = (d) => d >= S.settings.semStart && d <= semEnd();
let MEMO = { key: '', set: null, blocks: null };
const memoKey = () => `${S.settings.semStart}|${S.settings.weeks}|${S.settings.holidays.map((h) => h.date + h.name).join(',')}`;
function holSet() {
  const k = memoKey();
  if (MEMO.key !== k) MEMO = { key: k, set: new Set(S.settings.holidays.map((h) => h.date)), blocks: null };
  return MEMO.set;
}
const holName = (d) => (S.settings.holidays.find((h) => h.date === d) || {}).name || '';

function sessionsOn(d) {
  if (!inSem(d) || holSet().has(d)) return [];
  const w = D.wd(d), wk = semWeek(d);
  return S.schedule
    .filter((s) => Number(s.day) === w
      && (s.parity === 'all' || !s.parity || (s.parity === 'odd') === (wk % 2 === 1))
      && (!s.from || d >= s.from) && (!s.to || d <= s.to))
    .sort((a, b) => tmin(a.start) - tmin(b.start));
}
const early8 = (s) => tmin(s.start) < 9 * 60;
// 妹妹的課（同樣跳過國定假日與學期外）
function sisSessionsOn(d) {
  if (!S || !inSem(d) || holSet().has(d)) return [];
  const w = D.wd(d);
  return (S.sisSchedule || []).filter((s) => Number(s.day) === w).sort((a, b) => tmin(a.start) - tmin(b.start));
}
const sisEarly = (d) => sisSessionsOn(d).some(early8);
// 某一刻妹妹在做什麼（分鐘數 m 為當天 0:00 起算）
function sisStatus(d, m) {
  const ss = sisSessionsOn(d);
  const cur = ss.find((s) => m >= tmin(s.start) && m < tmin(s.end));
  const next = ss.find((s) => tmin(s.start) > m);
  const done = ss.filter((s) => tmin(s.end) <= m);
  let state = 'free';
  if (!ss.length) state = holName(d) ? 'holiday' : (D.wd(d) >= 6 ? 'weekend' : 'off');
  else if (cur) state = 'class';
  else if (!done.length) state = 'before';
  else if (next) state = (m >= 720 && m < 790) ? 'lunch' : 'break';
  else state = 'done';
  return { state, cur, next, done, list: ss, left: cur ? tmin(cur.end) - m : null, until: next ? tmin(next.start) - m : null };
}
// 兩人同一時段都有課
const overlapMin = (a, b) => Math.max(0, Math.min(tmin(a.end), tmin(b.end)) - Math.max(tmin(a.start), tmin(b.start)));
function sisOverlap(s, d) { return sisSessionsOn(d).filter((g) => overlapMin(s, g) >= 30); }
function sisTalk(g, k) { const t = SIS_TALK[g.id]; const arr = (t && t[k]) || []; return arr.length ? pick(arr) : ''; }
function sisShareLine(d) {
  const ss = sisSessionsOn(d);
  const withTalk = ss.filter((g) => SIS_TALK[g.id]);
  if (withTalk.length) return sisTalk(pick(withTalk), 'a');
  if (ss.length) return `今天上完${ss[ss.length - 1].name}了，好充實！`;
  return pick(holName(d) ? SIS_FREE.holiday : D.wd(d) >= 6 ? SIS_FREE.weekend : SIS_FREE.weekday);
}
const earlyAM = (s) => tmin(s.start) < 10 * 60;
const durMin = (s) => Math.max(0, tmin(s.end) - tmin(s.start));
const isLong = (s) => durMin(s) >= 110;

function holidayBlocks() {
  const hs = holSet();
  if (MEMO.blocks) return MEMO.blocks;
  const from = D.add(S.settings.semStart, -7), to = D.add(semEnd(), 14);
  const blocks = [];
  let cur = null;
  const close = () => { if (cur && cur.hol && D.diff(cur.start, cur.end) >= 2) blocks.push(cur); cur = null; };
  for (let d = from; d <= to; d = D.add(d, 1)) {
    const off = D.wd(d) >= 6 || hs.has(d);
    if (off) { if (!cur) cur = { start: d, end: d, hol: hs.has(d) }; else { cur.end = d; if (hs.has(d)) cur.hol = true; } } else close();
  }
  close();
  blocks.forEach((b) => {
    b.names = [...new Set(S.settings.holidays.filter((h) => h.date >= b.start && h.date <= b.end).map((h) => h.name))].join('、');
    b.postEnd = D.add(b.end, 7);
    b.announce = D.add(b.start, -3);
  });
  MEMO.blocks = blocks;
  return blocks;
}
function postBlock(d) { return holidayBlocks().find((b) => d > b.end && d <= b.postEnd); }
function firstClassAfter(b) {
  for (let d = D.add(b.end, 1); d <= b.postEnd; d = D.add(d, 1)) if (sessionsOn(d).length) return d;
  return null;
}
function midWindow() {
  const w = Number(S.settings.midWeek);
  if (!w || w < 3) return null;
  const start = D.add(S.settings.semStart, (w - 3) * 7);
  return { start, end: D.add(start, 13) };
}
function finWindow() { const end = semEnd(); return { start: D.add(end, -13), end }; }
const inWin = (w, d) => !!w && d >= w.start && d <= w.end;
const isNewbie = (d) => inSem(d) && semWeek(d) <= 3 && (!S.createdAt || d >= S.createdAt);
const newbieLeft = (d) => D.diff(d, D.add(S.settings.semStart, 20)) + 1;

function firstClassDayOfWeek(d) {
  if (!sessionsOn(d).length) return false;
  for (let x = D.monday(d); x < d; x = D.add(x, 1)) if (sessionsOn(x).length) return false;
  return true;
}
function hasGap(list) {
  for (let i = 1; i < list.length; i++) if (tmin(list[i].start) - tmin(list[i - 1].end) >= 60) return true;
  return false;
}

// 實際難度（熬夜後早課、收假後早課 → 地獄）
function effDiff(s, d, day) {
  let v = clamp(Number(s.diff) || 1, 1, 4);
  const tags = [];
  if (early8(s)) tags.push('早八');
  if (durMin(s) >= 170) tags.push('3 小時連堂');
  if (earlyAM(s) && day && day.sleep === 'late') { v = 4; tags.push('熬夜後早課'); }
  if (earlyAM(s) && postBlock(d)) { v = 4; tags.push('收假後早課'); }
  return { d: v, tags };
}

// ---------------------------------------------------------------------
//  等級與羈絆
// ---------------------------------------------------------------------
function levelFromExp(e) { let l = 1; for (let i = 2; i <= 5; i++) if (e >= LEVELS[i].need) l = i; return l; }
const lineOpen = (m) => S.player.level >= MEMBER[m].open;
const bondCap = () => (S.player.level >= 5 ? 4 : S.player.level >= 4 ? 2 : 1);
const affLevel = (a) => (a >= 85 ? 4 : a >= 60 ? 3 : a >= 35 ? 2 : 1);
const targetBond = (m) => (lineOpen(m) ? Math.min(bondCap(), affLevel(S.bonds[m].aff)) : 0);
const maxBuffs = () => (S.player.skills.wish ? 2 : 1);
const nameOf = (who) => (who === 'hero' ? S.profile.hero : S.profile.names[who]) || who;
const fill = (t) => String(t).replace(/\{(hero|mom|dad|sis)\}/g, (_, k) => nameOf(k));

function knowTarget() {
  const from = S.createdAt || today();
  const to = semEnd();
  let total = 0;
  for (let d = from; d <= to; d = D.add(d, 1)) {
    const ss = sessionsOn(d);
    if (!ss.length) continue;
    ss.forEach((s) => { total += DIFF[clamp(Number(s.diff) || 1, 1, 4)].know; });
    total += (inWin(midWindow(), d) || inWin(finWindow(), d)) ? 10 : 5;
  }
  return Math.max(60, Math.round(total));
}
function knowValue() { return clamp(Math.round(10 + 90 * Math.min(1, S.player.knowPts / knowTarget()) + S.player.knowBonus), 0, 100); }

// ---------------------------------------------------------------------
//  每日紀錄
// ---------------------------------------------------------------------
function playDate() {
  if (!S.started) return null;
  return S.settledThrough ? D.add(S.settledThrough, 1) : S.createdAt;
}
function newDay(d) {
  const prev = S.days[D.add(d, -1)];
  return {
    date: d, phase: 'morning', sleep: null, wake: null, buffs: [], reports: {}, moodAdj: 0,
    events: [], eventDone: false, candy: false, supply: false, inter: null, review: false,
    bedtimePrev: (prev && prev.bedtime) || S.settings.bedtime, bedtime: S.settings.bedtime,
    restart: false, settled: false, summary: null, begun: false, careShown: {}, postholShown: false,
  };
}
function getDay(d) { if (!S.days[d]) S.days[d] = newDay(d); return S.days[d]; }

function beginDay(d) {
  const day = getDay(d);
  if (day.begun) return day;
  day.begun = true;
  const wk = D.monday(d), mo = D.month(d);
  if (S.grants.week !== wk) {
    S.grants.week = wk;
    if (S.bonds.mom.lv >= 3) { S.items.supply++; toastLater(`🧺 ${nameOf('mom')}寄來本週的居家補給包`); }
    if (S.bonds.sis.lv >= 3) { S.items.candy++; toastLater(`🍬 ${nameOf('sis')}塞給你本週的元氣糖果`); }
  }
  if (S.grants.month !== mo) {
    S.grants.month = mo;
    if (S.bonds.dad.lv >= 3) { S.items.medal++; toastLater(`🎖️ ${nameOf('dad')}給你本月的堅毅勳章`); }
  }
  const avail = MEMBERS.filter((m) => S.bonds[m].lv >= 1);
  const prev = S.days[D.add(d, -1)];
  const keep = prev && prev.buffs ? prev.buffs.filter((m) => avail.includes(m)) : [];
  day.buffs = (keep.length ? keep : avail).slice(0, Math.min(maxBuffs(), avail.length));
  return day;
}

function remedyUsed(d) {
  let n = 0;
  const mon = D.monday(d);
  for (let x = mon; x <= D.add(mon, 6); x = D.add(x, 1)) {
    const day = S.days[x];
    if (!day) continue;
    Object.values(day.reports).forEach((r) => { if (r && r.remedied) n++; });
  }
  return n;
}
const remedyLeft = (d) => Math.max(0, 2 - remedyUsed(d));

function baseMood(d, day) {
  let m = 60;
  if (day.sleep === 'ok') m += 10; else if (day.sleep === 'late') m -= 10;
  if (day.wake === 'ok') m += 5; else if (day.wake === 'over') m -= 5;
  const b = postBlock(d);
  if (b && firstClassAfter(b) === d) m -= S.bonds.dad.lv >= 2 ? 10 : 20;
  m += day.moodAdj || 0;
  if (day.candy) m += 10;
  if (day.restart) m = Math.max(m, 60);
  return clamp(m, 0, 100);
}

// ---------------------------------------------------------------------
//  計算一天的獎勵（預覽與結算共用）
// ---------------------------------------------------------------------
function computeDay(d, day) {
  const P = S.player.skills, wish = !!P.wish;
  const R = { list: [], exp: 0, know: 0, aff: { mom: 0, dad: 0, sis: 0 }, disc: 0, grit: 0, notes: [], counted: 0, nonLeave: 0, attended: 0, weighted: 0, pending: 0, anyAbsent: false, anyLeft: false };
  const sessions = sessionsOn(d);
  let mood = baseMood(d, day), fatigue = 0, firstLate = false, prevFail = false;
  const streak = S.streak.attend;
  const ph = postBlock(d), firstWk = firstClassDayOfWeek(d), fin = inWin(finWindow(), d), newbie = isNewbie(d);
  let anyEarly = false, anyHard = false;
  for (const s of sessions) {
    const rep = day.reports[s.id];
    const o = rep && rep.o;
    const e = effDiff(s, d, day);
    const it = { s, rep, o, d: e.d, tags: e.tags, exp: 0, know: 0, aff: 0, disc: 0, grit: 0, bonus: 0, why: [] };
    R.list.push(it);
    if (!o) { R.pending++; continue; }
    if (o === 'cancel') continue;
    R.counted++;
    if (o !== 'leave') R.nonLeave++;
    const base = DIFF[e.d];
    let f = OUT[o].factor;
    if (o === 'late' && P.commute && !firstLate) { f = 1; it.why.push('通勤神速：遲到視同準時'); }
    if (o === 'late') firstLate = true;
    const present = o === 'perfect' || o === 'late' || o === 'left';
    const attended = o === 'perfect' || o === 'late' || (o === 'left' && rep.medal);
    let bonus = 0;
    if (present) {
      if (newbie) { bonus += 30; it.why.push('新手期 +30%'); }
      if (fin) { bonus += 20; it.why.push('期末最終決戰 +20%'); }
      if (streak >= 7) { bonus += 50; it.why.push(`連續全勤 ${streak} 天 +50%`); } else if (streak >= 3) { bonus += 20; it.why.push(`連續全勤 ${streak} 天 +20%`); }
      if (mood >= 80 && (fatigue < 70 || day.candy)) { bonus += 10; it.why.push('好心情 +10%'); }
      if (early8(s) && P.dawn) { bonus += 15; it.why.push('晨光感知 +15%'); }
      if (early8(s) && P.clock && S.streak.wake >= 3) { bonus += 10; it.why.push('生物鐘校準 +10%'); }
      if (isLong(s) && P.endure) { bonus += 15; it.why.push('久坐耐性 +15%'); }
      if (firstWk && P.weekend) { bonus += 25; it.why.push('週末節律 +25%'); }
      if (ph && P.holiday) { bonus += 30; it.why.push('連假抗性 +30%'); }
      if (prevFail && P.window && attended) { bonus += 50; it.why.push('破窗免疫：止損反擊 +50%'); }
    }
    it.bonus = bonus;
    if (o === 'absent') {
      if (rep.remedied) { it.exp = Math.round(base.exp * 0.5); it.know = Math.round(base.know * 0.5); it.aff = effAff(s.guardian, base.aff * 0.5); it.why.push('補救任務：恢復 50%'); }
      else it.aff = -1;
    } else if (o !== 'leave') {
      const mut = P.mutual && e.d >= 3 ? 1.5 : 1;
      it.exp = Math.round(base.exp * f * (1 + bonus / 100));
      it.know = Math.round(base.know * f);
      it.aff = effAff(s.guardian, base.aff * f * mut);
      if (mut > 1) it.why.push('雙向牽掛：好感 ×1.5');
    }
    if (early8(s)) { if (o === 'perfect') it.disc += 1; else if (o === 'late') it.disc += 0.5; }
    if (e.d >= 3 && o === 'perfect') it.grit += 1;
    if (o === 'left' && !rep.medal && !P.window) it.grit -= 3;
    if (present) fatigue += durMin(s) / 60 * 10 * (isLong(s) && P.endure ? 0.85 : 1);
    if (attended) {
      R.attended++;
      if (early8(s)) anyEarly = true;
      if (e.d >= 3) anyHard = true;
      if (day.buffs.includes('sis') && s.guardian === 'sis' && S.bonds.sis.lv >= 1) mood = clamp(mood + 10 * (wish ? 1.1 : 1), 0, 100);
    }
    R.weighted += (o === 'perfect' || o === 'late') ? 1 : o === 'left' ? (rep.medal ? 1 : 0.5) : 0;
    if (o === 'absent' && !rep.remedied) R.anyAbsent = true;
    if (o === 'left' && !rep.medal) R.anyLeft = true;
    prevFail = (o === 'absent' || o === 'left') ? true : (attended ? false : prevFail);
    R.exp += it.exp; R.know += it.know; R.aff[s.guardian] = r1((R.aff[s.guardian] || 0) + it.aff); R.disc += it.disc; R.grit += it.grit;
  }
  if (day.candy) fatigue = 0;
  R.mood = Math.round(mood);
  R.fatigue = clamp(Math.round(fatigue), 0, 100);
  R.classDay = sessions.length > 0;
  const nl = R.list.filter((x) => x.o && x.o !== 'cancel' && x.o !== 'leave');
  R.fullAttend = nl.length > 0 && R.pending === 0 && nl.every((x) => x.o === 'perfect' || x.o === 'late' || (x.o === 'left' && x.rep.medal));
  const cnt = R.list.filter((x) => x.o && x.o !== 'cancel');
  R.perfectAll = cnt.length > 0 && R.pending === 0 && cnt.every((x) => x.o === 'perfect');

  const bm = wish ? 1.1 : 1;
  if (day.buffs.includes('mom') && S.bonds.mom.lv >= 1 && anyEarly) {
    const v = 5 * (S.bonds.mom.lv >= 4 ? 2 : 1) * bm;
    R.disc += v; R.notes.push(`🍱 愛心早餐：自律 +${r1(v)}`);
  }
  if (day.buffs.includes('dad') && S.bonds.dad.lv >= 1 && anyHard) {
    const v = 5 * bm;
    R.grit += v; R.notes.push(`🛡️ 沉穩信念：堅毅 +${r1(v)}`);
  }
  if (R.fullAttend) { R.grit += 2; R.notes.push('全日出席：堅毅 +2'); }
  if (R.fullAttend && P.stay && hasGap(sessions.filter((s) => { const r = day.reports[s.id]; return r && r.o !== 'cancel'; }))) {
    R.exp += 10; R.grit += 3; R.notes.push('空檔續航：經驗 +10、堅毅 +3');
  }
  if (R.perfectAll) {
    const be = Math.round(R.exp * 0.5);
    R.exp += be;
    MEMBERS.forEach((m) => { if (R.aff[m] > 0) R.aff[m] = r1(R.aff[m] * 1.5); });
    R.notes.push(`☀️ 全日完美通關：經驗與好感 ×1.5（經驗 +${be}）`);
  }
  // 兄妹同步早八：妹妹今天也是早八，你準時（或遲到但有到）出席了早八
  if (sisEarly(d)) {
    const hit = R.list.find((x) => early8(x.s) && (x.o === 'perfect' || x.o === 'late'));
    R.syncPossible = R.list.some((x) => early8(x.s));
    if (hit) {
      R.sync = true;
      R.exp += 10;
      const v = effAff('sis', 3);
      R.aff.sis = r1((R.aff.sis || 0) + v);
      R.notes.push(`⚡ 兄妹同步早八：經驗 +10、${nameOf('sis')}好感 +${v}`);
    }
  }
  // 作息
  const protect = (day.buffs.includes('mom') && S.bonds.mom.lv >= 1) || S.bonds.mom.lv >= 4 || day.supply;
  if (day.sleep === 'ok') { R.disc += 1; R.notes.push('準時就寢：自律 +1'); }
  else if (day.sleep === 'late') { R.disc -= 2; R.notes.push('熬夜：自律 −2'); }
  if (day.wake === 'ok') { R.disc += 2; R.notes.push('準時起床：自律 +2'); }
  else if (day.wake === 'snooze' || day.wake === 'over') {
    let pen = day.wake === 'over' ? 1 : 0;
    if (S.streak.prevWakeBad) pen += 1;
    if (protect && pen > 0) R.notes.push(day.supply ? '🧺 居家補給包：抵消賴床失敗' : '媽媽的安撫：起床失敗不扣自律');
    else if (pen > 0) { R.disc -= pen; R.notes.push(`${S.streak.prevWakeBad ? '連續賴床' : '睡過頭'}：自律 −${pen}`); }
  }
  if (day.review) {
    const k = (inWin(midWindow(), d) || fin) ? 10 : 5;
    R.know += k; R.notes.push(`課後複習：學識點 +${k}`);
  }
  if (day.inter) {
    const v = effAff(day.inter.who, 1 + (day.inter.special ? 2 : 0));
    R.aff[day.inter.who] = r1(R.aff[day.inter.who] + v);
    R.notes.push(`晚間${LINES.interType[day.inter.type]}：${nameOf(day.inter.who)}好感 +${v}`);
  }
  if (R.anyAbsent && S.streak.prevAbsent && !day.restart) { R.grit -= 2; R.notes.push('連續缺課：堅毅 −2'); }
  R.discEff = effAttr('disc', R.disc);
  R.gritEff = effAttr('grit', R.grit);
  if ((R.disc > 0 && R.discEff < r1(R.disc)) || (R.grit > 0 && R.gritEff < r1(R.grit))) {
    R.notes.push(`屬性越高提升越慢：自律實得 ${signed(R.discEff)}、堅毅實得 ${signed(R.gritEff)}`);
  }
  return R;
}

// ---------------------------------------------------------------------
//  結算
// ---------------------------------------------------------------------
function snapshotItems(d, day, R) {
  return R.list.map((x) => ({
    id: x.s.id, name: x.s.name, start: x.s.start, end: x.s.end, guardian: x.s.guardian, d: x.d,
    early8: early8(x.s), o: x.o || 'none', remedied: !!(x.rep && x.rep.remedied), medal: !!(x.rep && x.rep.medal),
  }));
}

function settleDay(d) {
  const day = getDay(d);
  const R = computeDay(d, day);
  CTX_DATE = d;
  try { return settleInner(d, day, R); } finally { CTX_DATE = null; }
}

function settleInner(d, day, R) {
  const sum = { date: d, exp: R.exp, know: R.know, aff: { ...R.aff }, disc: R.discEff, grit: R.gritEff, notes: R.notes.slice(), lines: [], levelUps: [], bondUps: [] };
  // 套用
  S.player.exp += R.exp;
  S.player.knowPts += R.know;
  S.player.disc = clamp(r1(S.player.disc + R.discEff), 0, 100);
  S.player.grit = clamp(r1(S.player.grit + R.gritEff), 0, 100);
  MEMBERS.forEach((m) => { S.bonds[m].aff = clamp(r1(S.bonds[m].aff + (R.aff[m] || 0)), 0, 100); });

  const items = snapshotItems(d, day, R);
  const counted = items.filter((x) => x.o !== 'cancel');
  const unreported = items.filter((x) => x.o === 'none').length;
  const classDay = counted.length > 0;
  const nonLeave = counted.filter((x) => x.o !== 'leave');
  const full = nonLeave.length > 0 && nonLeave.every((x) => x.o === 'perfect' || x.o === 'late' || (x.o === 'left' && x.medal));
  const bad = R.anyAbsent || R.anyLeft || unreported > 0;

  // 連續紀錄
  if (classDay) {
    if (nonLeave.length > 0) {
      if (full) { S.streak.attend++; S.counters.maxAttend = Math.max(S.counters.maxAttend, S.streak.attend); } else S.streak.attend = 0;
    }
    S.streak.bad = bad ? S.streak.bad + 1 : 0;
    S.streak.prevAbsent = (R.anyAbsent || unreported > 0) && !day.restart;
    S.streak.noMiss = bad ? 0 : S.streak.noMiss + 1;
  } else {
    S.streak.noMiss++;
  }
  if (day.wake === 'ok' || day.supply) S.streak.wake++; else S.streak.wake = 0;
  S.streak.prevWakeBad = (day.wake === 'snooze' || day.wake === 'over') && !day.supply;
  if (day.restart) { S.streak.bad = 0; S.streak.prevWakeBad = false; }

  // 計數
  counted.forEach((x) => { if ((x.o === 'perfect' || x.o === 'late') && x.early8) S.counters.early++; });
  if (counted.some((x) => x.o === 'perfect')) unlockAch('first');
  if (R.perfectAll) unlockAch('fullday');

  // 兄妹同步早八
  if (R.sync) {
    S.counters.sync++;
    if (!S.syncDays.includes(d)) S.syncDays.push(d);
    if (S.counters.sync === 1) { queueStory('sync'); }
    const wkSync = S.syncDays.filter((x) => D.monday(x) === D.monday(d)).length;
    if (wkSync >= 2) unlockAch('syncweek');
    if (S.counters.sync >= 10 && !S.achievements.sync10) { unlockAch('sync10'); unlockCollect('drink'); queueStory('syncAlly'); }
    sum.lines.push(`⚡ 兄妹同步早八（第 ${S.counters.sync} 次）：${nameOf('sis')}：「${pick(['平手！下次我要贏！', '報到成功～我們都好棒！', '今天也一起撐過早八了！'])}」`);
  }
  // 妹妹的分享（羈絆 Lv2）
  if (S.bonds.sis.lv >= 2) {
    S.counters.boring += counted.filter((x) => (x.o === 'perfect' || x.o === 'late') && (x.guardian === 'sis' || x.d === 1)).length;
    while (S.counters.boring >= 3) {
      S.counters.boring -= 3;
      const msg = Math.random() < 0.7 ? sisShareLine(d) : pick(LINES.sisShares);
      S.shares.unshift({ d, t: msg });
      if (S.shares.length > 40) S.shares.length = 40;
      sum.lines.push(`📱 ${nameOf('sis')}：「${msg}」`);
    }
  }
  // 弱項攻克
  const weak = new Set(S.settings.weakIds || []);
  counted.filter((x) => weak.has(x.id)).forEach((x) => {
    if (x.o === 'perfect' || x.o === 'late') S.counters.weakRun++;
    else if (x.o === 'absent' || x.o === 'left' || x.o === 'none') S.counters.weakRun = 0;
    if (S.counters.weakRun >= 5) {
      S.counters.weakRun = 0;
      S.counters.weakDone++;
      S.items.candy += 2;
      unlockAch('weak');
      queueStory('weak');
      sum.lines.push('⚔️ 弱項攻克成功！獲得元氣糖果 ×2');
      logEv('弱項攻克成功：連續 5 次出席最抗拒的課', d);
    }
  });

  // 歸家動力
  if (S.player.skills.home && D.wd(d) === 5 && classDay && full) {
    const g = MEMBERS.map((m) => `${nameOf(m)} +${addAff(m, 3)}`).join('、');
    queueStory('weekend');
    sum.lines.push(`🏠 歸家動力：週末團聚，好感 ${g}`);
  }

  // 低谷自動關懷
  if (S.streak.bad >= 3) {
    S.streak.bad = 0;
    S.streak.prevAbsent = false;
    S.streak.prevWakeBad = false;
    queueStory('care');
    sum.lines.push('🌙 家人察覺你最近有點累，送來了關心。');
  }

  day.settled = true;
  day.phase = 'done';
  day.summary = { sync: !!R.sync, items, exp: R.exp, know: R.know, aff: { ...R.aff }, disc: R.discEff, grit: R.gritEff, notes: R.notes, wake: day.wake, sleep: day.sleep, supply: day.supply, review: day.review, full, perfect: R.perfectAll, classDay, mood: R.mood };
  S.settledThrough = d;

  // 週期性評估
  if (D.wd(d) === 7) evalWeek(d, sum);
  if (D.month(D.add(d, 1)) !== D.month(d)) evalMonth(d, sum);
  evalHolidays(d, sum);
  evalMidterm(d, sum);

  progressUpdate(sum);
  checkAchievements();
  const att = counted.length ? `${counted.filter((x) => x.o === 'perfect' || x.o === 'late').length}/${counted.length} 堂出席` : '休息日';
  logEv(`結算 ${D.label(d)}：${att}，經驗 +${R.exp}`, d);
  if (d >= semEnd() && !S.ending) triggerEnding(sum);
  save();
  return sum;
}

function skipDay(d) {
  getDay(d);
  return settleDay(d);
}

// ---------------------------------------------------------------------
//  每週、每月、限時活動
// ---------------------------------------------------------------------
function daysRange(a, b) {
  const out = [];
  for (let x = a; x <= b; x = D.add(x, 1)) out.push(x);
  return out;
}
function summaryItems(d) { const s = S.days[d] && S.days[d].summary; return s ? s.items : null; }

function weekStatus(mon) {
  const days = daysRange(mon, D.add(mon, 6)).filter((x) => S.createdAt && x >= S.createdAt);
  let early = 0, earlyOk = 0, classDays = 0, left = 0, fullAbsentDays = 0, earlyPending = 0;
  days.forEach((x) => {
    let items = summaryItems(x);
    let pending = false;
    if (!items) {
      if (x > today() || !S.days[x]) {
        const ss = sessionsOn(x);
        early += ss.filter(early8).length; earlyPending += ss.filter(early8).length;
        return;
      }
      const R = computeDay(x, S.days[x]);
      items = snapshotItems(x, S.days[x], R);
      pending = true;
    }
    const c = items.filter((i) => i.o !== 'cancel');
    if (!c.length) return;
    classDays++;
    c.forEach((i) => {
      if (i.early8 && i.o !== 'leave') {
        early++;
        if (i.o === 'perfect' || i.o === 'late') earlyOk++;
        else if (i.o === 'none' && pending) earlyPending++;
      }
      if (i.o === 'left' && !i.medal) left++;
    });
    const nl = c.filter((i) => i.o !== 'leave');
    if (!pending && nl.length && nl.every((i) => (i.o === 'absent' && !i.remedied) || i.o === 'none')) fullAbsentDays++;
  });
  return { early, earlyOk, earlyPending, classDays, left, fullAbsentDays, days: days.length };
}

function evalWeek(sun, sum) {
  const mon = D.add(sun, -6);
  if (S.weekly[mon] && S.weekly[mon].done) return;
  const st = weekStatus(mon);
  const rec = { done: true, disc: null, grit: null };
  if (S.player.level >= 3 && st.days > 0) {
    rec.disc = st.early > 0 && st.earlyOk === st.early;
    if (rec.disc) {
      S.player.sp++;
      const g = MEMBERS.map((m) => `${nameOf(m)} +${addAff(m, 5)}`).join('、');
      sum.lines.push(`🎁 週自律挑戰成功（早八全勤）：技能點 +1、好感 ${g}`);
      logEv('週自律挑戰成功', sun);
    }
    rec.grit = st.classDays > 0 && st.left === 0 && st.fullAbsentDays === 0;
    if (rec.grit) {
      const gg = addAttr('grit', 10), ga = addAff('dad', 8);
      sum.lines.push(`🎁 週堅毅挑戰成功：堅毅 +${gg}、${nameOf('dad')}好感 +${ga}`);
      logEv('週堅毅挑戰成功', sun);
    }
  }
  S.weekly[mon] = rec;
  sibWeekly(mon, sum);
}

function sibWeekly(mon, sum) {
  if (S.sibWeekly[mon]) return;
  let mine = 0, mineOk = 0, hers = 0;
  daysRange(mon, D.add(mon, 6)).forEach((x) => {
    hers += sisSessionsOn(x).length;
    if (!S.createdAt || x < S.createdAt) return;
    const items = summaryItems(x);
    if (!items) return;
    items.filter((i) => i.o !== 'cancel' && i.o !== 'leave').forEach((i) => { mine++; if (i.o === 'perfect' || i.o === 'late') mineOk++; });
  });
  const sync = S.syncDays.filter((x) => D.monday(x) === mon).length;
  S.sibWeekly[mon] = { mine, mineOk, hers, sync };
  if (!mine && !hers) return;
  const wk = inSem(mon) ? `第 ${semWeek(mon)} 週` : D.md(mon) + ' 那週';
  sum.lines.push(`📮 兄妹週報（${wk}）：你出席 ${mineOk}/${mine} 堂，${nameOf('sis')}這週有 ${hers} 堂課，同步早八 ${sync} 次。${nameOf('sis')}：「${mineOk === mine && mine ? '哥這週全勤！我也沒翹課喔～' : '下週我們一起再加油！'}」`);
}

function monthStatus(mo) {
  const first = mo + '-01';
  let last = first;
  while (D.month(D.add(last, 1)) === mo) last = D.add(last, 1);
  let miss = 0, classDays = 0;
  daysRange(first, last).filter((x) => S.createdAt && x >= S.createdAt && x <= (S.settledThrough || '')).forEach((x) => {
    const items = summaryItems(x);
    if (!items) return;
    const c = items.filter((i) => i.o !== 'cancel');
    if (c.length) classDays++;
    c.forEach((i) => { if ((i.o === 'absent' && !i.remedied) || i.o === 'none') miss++; });
  });
  return { miss, classDays, first, last };
}

function evalMonth(d, sum) {
  const mo = D.month(d);
  if (S.monthly[mo]) return;
  if (S.player.level < 4) { S.monthly[mo] = { done: true, ok: null }; return; }
  const st = monthStatus(mo);
  const ok = st.classDays > 0 && st.miss <= 1;
  S.monthly[mo] = { done: true, ok };
  if (ok) {
    S.player.disc = clamp(S.player.disc + 10, 0, 100);
    S.player.grit = clamp(S.player.grit + 10, 0, 100);
    S.player.knowBonus += 10;
    unlockCollect('cake');
    queueStory('monthly');
    sum.lines.push('🗓️ 月度成長挑戰成功：全屬性 +10');
    logEv('月度成長挑戰成功', d);
  }
}

function holidayStatus(b) {
  if (!S.createdAt || b.start < S.createdAt) return { state: 'missed' };
  const rec = S.holidayEv[b.start];
  if (rec && rec.done) return { state: rec.ok ? 'won' : 'lost' };
  const t = playDate() || today();
  if (t < b.announce) return { state: 'future' };
  let wakeOk = 0, wakeFail = 0;
  daysRange(b.start, b.end).forEach((x) => {
    const sm = S.days[x] && S.days[x].summary;
    if (!sm) return;
    if (sm.wake === 'ok' || sm.supply) wakeOk++; else wakeFail++;
  });
  let postFail = 0, postClass = 0;
  daysRange(D.add(b.end, 1), b.postEnd).forEach((x) => {
    const items = summaryItems(x);
    if (!items) return;
    const c = items.filter((i) => i.o !== 'cancel' && i.o !== 'leave');
    if (c.length) postClass++;
    if (c.some((i) => (i.o === 'absent' && !i.remedied) || (i.o === 'left' && !i.medal) || i.o === 'none')) postFail++;
  });
  const total = D.diff(b.start, b.end) + 1;
  return { state: t < b.start ? 'announce' : t <= b.end ? 'during' : 'post', wakeOk, wakeFail, total, postFail, postClass, failed: wakeFail > 0 || postFail > 0 };
}

function evalHolidays(d, sum) {
  holidayBlocks().forEach((b) => {
    if (d !== b.postEnd) return;
    if (!S.createdAt || b.start < S.createdAt) return;
    if (S.holidayEv[b.start] && S.holidayEv[b.start].done) return;
    const st = holidayStatus(b);
    const ok = !st.failed && st.wakeOk === st.total;
    S.holidayEv[b.start] = { done: true, ok };
    if (ok) {
      MEMBERS.forEach((m) => { S.bonds[m].aff = clamp(S.bonds[m].aff + 10, 0, 100); });
      S.items.supply++; S.items.candy++; S.items.medal++;
      S.counters.holidayWins++;
      unlockCollect('photo');
      queueStory('holiday');
      sum.lines.push(`🏔️ 連假守護戰（${b.names}）成功：全員好感 +10，獲得家族團圓禮包（補給包、糖果、勳章各 1）`);
      logEv(`連假守護戰成功（${b.names}）`, d);
    } else {
      sum.lines.push(`🏔️ 連假守護戰（${b.names}）結束。這次沒能全部達成，下一次連假再一起守護作息。`);
    }
  });
}

function midStatus() {
  const w = midWindow();
  if (!w) return { state: 'none' };
  if (!S.createdAt || w.end < S.createdAt) return { state: 'missed', w };
  const rec = S.midEv[w.start];
  if (rec && rec.done) return { state: rec.ok ? 'won' : 'lost', w };
  const t = playDate() || today();
  let energy = 0;
  daysRange(w.start, w.end).filter((x) => x >= S.createdAt).forEach((x) => {
    const sm = S.days[x] && S.days[x].summary;
    if (!sm) return;
    energy += sm.items.filter((i) => i.o === 'perfect' || i.o === 'late').length + (sm.review ? 1 : 0);
  });
  return { state: t < w.start ? 'future' : 'active', w, energy };
}

function evalMidterm(d, sum) {
  const w = midWindow();
  if (!w || d !== w.end || !S.createdAt || w.end < S.createdAt) return;
  if (S.midEv[w.start] && S.midEv[w.start].done) return;
  const st = midStatus();
  const ok = (st.energy || 0) >= 10;
  S.midEv[w.start] = { done: true, ok };
  if (ok) { queueStory('midterm'); sum.lines.push('📖 期中衝刺季完成：解鎖爸爸的考前加油'); }
}

// ---------------------------------------------------------------------
//  升級、羈絆、成就
// ---------------------------------------------------------------------
function allPlus(n) {
  S.player.disc = clamp(S.player.disc + n, 0, 100);
  S.player.grit = clamp(S.player.grit + n, 0, 100);
  S.player.knowBonus += n;
}

function progressUpdate(sum) {
  sum = sum || { lines: [], levelUps: [], bondUps: [] };
  const nl = levelFromExp(S.player.exp);
  while (S.player.level < nl) {
    S.player.level++;
    S.player.sp++;
    sum.levelUps.push(S.player.level);
    S.queue.push({ type: 'levelup', lv: S.player.level });
    logEv(`升級到 Lv${S.player.level}「${LEVELS[S.player.level].title}」`);
    if (S.player.level === 5) { unlockAch('lv5'); queueStory('finale'); }
  }
  MEMBERS.forEach((m) => {
    const t = targetBond(m);
    while (S.bonds[m].lv < t) {
      S.bonds[m].lv++;
      const lv = S.bonds[m].lv;
      sum.bondUps.push({ m, lv });
      queueStory(m + lv);
      if (BOND_COLLECT[m + lv]) unlockCollect(BOND_COLLECT[m + lv]);
      if (m === 'dad' && lv === 4 && !S.flags.dad4) { S.flags.dad4 = true; allPlus(5); }
      if (m === 'sis' && lv === 4 && !S.flags.sis4) { S.flags.sis4 = true; allPlus(3); }
      logEv(`${nameOf(m)}羈絆提升到 Lv${lv}「${BOND_PERKS[m][lv].name}」`);
    }
  });
  if (S.player.skills.resonance && !S.flags.resonance && MEMBERS.every((m) => S.bonds[m].lv >= 3)) {
    S.flags.resonance = true;
    allPlus(5);
    sum.lines.push('💫 羈絆共鳴：永久全屬性 +5');
    logEv('羈絆共鳴發動：永久全屬性 +5');
  }
  checkAchievements();
  return sum;
}

function unlockAch(id) {
  if (S.achievements[id]) return;
  S.achievements[id] = nowDate();
  const a = ACHV.find((x) => x.id === id);
  if (a) { toastLater(`${a.icon} 解鎖徽章「${a.name}」`); logEv(`解鎖徽章「${a.name}」`); }
}
function unlockCollect(id) {
  if (S.collection[id]) return;
  S.collection[id] = nowDate();
  const c = COLLECTION[id];
  if (c) logEv(`獲得收藏「${c.name}」`);
}
function checkAchievements() {
  if (S.counters.early >= 20) unlockAch('dawn20');
  if (S.streak.attend >= 7 || S.counters.maxAttend >= 7) unlockAch('week7');
  if (S.streak.noMiss >= 30) unlockAch('nomiss30');
  if (S.counters.holidayWins >= 3) unlockAch('holiday3');
  if (S.counters.remedies >= 3) unlockAch('remedy3');
  if (S.counters.events >= 10) unlockAch('trial10');
  if (S.counters.companion >= 3) unlockAch('companion');
  if (S.started && knowValue() >= 80) unlockAch('know80');
  if (MEMBERS.every((m) => S.bonds[m].aff >= 85)) unlockAch('bond');
  if (S.player.level >= 5) unlockAch('lv5');
}

function queueStory(id) {
  if (!STORIES[id]) return;
  if (!S.album[id]) S.album[id] = nowDate();
  S.queue.push({ type: 'story', id });
}

// ---------------------------------------------------------------------
//  出勤統計與結局
// ---------------------------------------------------------------------
function attendanceStats(from, to) {
  const st = { counted: 0, weighted: 0, perfect: 0, late: 0, left: 0, absent: 0, leave: 0, none: 0, cancel: 0 };
  if (!from) return { ...st, rate: null };
  for (let d = from; d <= to; d = D.add(d, 1)) {
    const items = summaryItems(d);
    if (!items) continue;
    items.forEach((i) => {
      st[i.o] = (st[i.o] || 0) + 1;
      if (i.o === 'cancel') return;
      st.counted++;
      st.weighted += (i.o === 'perfect' || i.o === 'late') ? 1 : i.o === 'left' ? (i.medal ? 1 : 0.5) : 0;
    });
  }
  st.rate = st.counted ? st.weighted / st.counted : null;
  return st;
}
function bondTotal() { return Math.floor(MEMBERS.reduce((a, m) => a + S.bonds[m].aff, 0)); }
function semGrade(rate, know) {
  if (rate >= 0.9 && know >= 90) return 'S';
  if (rate >= 0.8 && know >= 75) return 'A';
  if (rate >= 0.7 && know >= 60) return 'B';
  return 'C';
}
function endingType(rate, bt) {
  if (rate >= 0.9 && bt >= 200) return 'perfect';
  if (rate >= 0.7 && bt >= 120) return 'steady';
  return 'regret';
}
function triggerEnding(sum) {
  const st = attendanceStats(S.createdAt, semEnd());
  const rate = st.rate == null ? 0 : st.rate;
  const bt = bondTotal();
  const type = endingType(rate, bt);
  const kv = knowValue();
  S.ending = { type, rate, bond: bt, know: kv, grade: semGrade(rate, kv), date: semEnd(), level: S.player.level, dadPride: S.bonds.dad.lv >= 4 };
  if (rate >= 0.9) unlockAch('pride');
  if (type === 'perfect') unlockCollect('golden');
  queueStory('ending_' + type);
  sum && sum.lines.push('🎓 學期結束！結局已解鎖，紀念冊全部開放回顧。');
  logEv(`學期結算：${{ perfect: '完美成長', steady: '穩步向前', regret: '留有遺憾' }[type]}結局（出勤 ${Math.round(rate * 100)}%、羈絆 ${bt}）`, semEnd());
}

// ---------------------------------------------------------------------
//  試煉事件
// ---------------------------------------------------------------------
function applyFx(fx, d) {
  const out = [];
  const day = getDay(d);
  Object.entries(fx || {}).forEach(([k, v]) => {
    if (!v) return;
    if (k === 'disc' || k === 'grit') { const e = addAttr(k, v); out.push(`${k === 'disc' ? '自律' : '堅毅'} ${signed(e)}`); }
    else if (k === 'know') { S.player.knowPts = Math.max(0, S.player.knowPts + v); out.push(`學識點 ${signed(v)}`); }
    else if (k === 'mood') { day.moodAdj = (day.moodAdj || 0) + v; out.push(`心情 ${signed(v)}`); }
    else if (MEMBERS.includes(k)) { const e = addAff(k, v); out.push(`${nameOf(k)}好感 ${signed(e)}`); }
    else if (k === 'companion') { S.counters.companion += v; out.push('同伴影響力 +' + v); }
  });
  return out;
}

function pickEvent(d) {
  const recent = new Set(S.recentEvents || []);
  const day = d || nowDate();
  const ok = (e) => !e.sisCourse || sisSessionsOn(day).some((g) => g.id === e.sisCourse);
  const pool = EVENTS.filter((e) => !recent.has(e.id) && ok(e));
  const ev = pick(pool.length ? pool : EVENTS.filter(ok));
  S.recentEvents = [ev.id, ...(S.recentEvents || [])].slice(0, 8);
  return ev;
}

// =====================================================================
//  介面：繪製畫面、對話框、操作處理
// =====================================================================

let TAB = 'today';
let modalOpen = false;
let pendingToasts = [];
const UI = { interWho: null, story: null, event: null, recDetail: null, sibDate: null };

const $ = (sel, root = document) => root.querySelector(sel);
function toastLater(msg) { pendingToasts.push(msg); }
function showToasts() {
  const box = $('#toasts');
  if (!box) return;
  while (pendingToasts.length) {
    const msg = pendingToasts.shift();
    const el = document.createElement('div');
    el.className = 'toast';
    el.textContent = msg;
    box.appendChild(el);
    setTimeout(() => el.classList.add('out'), 2800);
    setTimeout(() => el.remove(), 3300);
  }
}
const toast = (msg) => { toastLater(msg); if (!modalOpen) showToasts(); };

const starHTML = (n) => `<span class="stars" aria-label="${n} 星">${'★'.repeat(n)}<span class="dim">${'★'.repeat(4 - n)}</span></span>`;
const btn = (act, label, on = false, cls = '', extra = '') => `<button class="btn ${cls}${on ? ' on' : ''}" data-act="${act}" ${extra}>${label}</button>`;
const chip = (t, cls = '') => `<span class="chip ${cls}">${t}</span>`;
function bar(v, max, cls) { const p = clamp((v / max) * 100, 0, 100); return `<div class="bar ${cls}"><i style="width:${p.toFixed(1)}%"></i></div>`; }

// ---------------------------------------------------------------------
//  主繪製
// ---------------------------------------------------------------------
function render() {
  const top = $('#top'), tabs = $('#tabs'), view = $('#view');
  if (!S.started) {
    top.innerHTML = `<div class="brand"><b>晨光羈絆</b><span>學園修行物語</span></div>`;
    tabs.hidden = true;
    view.innerHTML = renderWelcome();
    return;
  }
  const pd = playDate();
  if (pd && pd <= today() && pd <= semEnd()) { beginDay(pd); }
  top.innerHTML = renderTop();
  tabs.hidden = false;
  const T = [['today', '今日'], ['sib', '兄妹'], ['bonds', '羈絆'], ['skills', '技能'], ['quests', '挑戰'], ['album', '紀念冊'], ['records', '紀錄'], ['settings', '設定']];
  tabs.innerHTML = T.map(([k, n]) => {
    const badge = (k === 'skills' && S.player.level >= 2 && S.player.sp > 0) ? `<em>${S.player.sp}</em>` : '';
    return `<button class="tab${TAB === k ? ' on' : ''}" data-act="tab:${k}">${n}${badge}</button>`;
  }).join('');
  const R = { today: renderToday, sib: renderSibling, bonds: renderBonds, skills: renderSkills, quests: renderQuests, album: renderAlbum, records: renderRecords, settings: renderSettings }[TAB] || renderToday;
  view.innerHTML = R();
  if (!storageOK) view.insertAdjacentHTML('afterbegin', `<div class="warn">⚠️ 這個瀏覽器不允許儲存資料，關掉頁面後進度會消失。請到「設定」匯出存檔備份。</div>`);
  save();
  if (!modalOpen) showToasts();
}

function renderTop() {
  const L = S.player.level, nx = LEVELS[L + 1];
  const cur = LEVELS[L].need;
  const prog = nx ? (S.player.exp - cur) / (nx.need - cur) : 1;
  const title = (S.ending && S.ending.type === 'perfect') ? '家庭支柱' : LEVELS[L].title;
  return `<div class="brand"><b>晨光羈絆</b><span>學園修行物語</span></div>
  <div class="me">
    <div class="me-av">${portrait('hero', 'smile', 'casual')}</div>
    <div class="me-txt"><div><b>${esc(S.profile.hero)}</b> <span class="lv">Lv${L}</span> <span class="ttl">${title}</span></div>
      <div class="exp">${bar(prog, 1, 'xp')}<small>${nx ? `${S.player.exp} / ${nx.need} 經驗` : `${S.player.exp} 經驗 · 已滿級`}</small></div></div>
    <button class="icon-btn" data-act="help" title="遊戲說明" aria-label="遊戲說明">？</button>
  </div>`;
}

// ---------------------------------------------------------------------
//  歡迎畫面
// ---------------------------------------------------------------------
function renderWelcome() {
  const t = today(), tm = D.add(t, 1);
  return `<div class="welcome card">
    <div class="w-scene">${scene('bedroom', { time: 'morning', actors: [['hero', 'happy', 'casual', 218, 112, 252]] })}</div>
    <h1>晨光羈絆：學園修行物語</h1>
    <p class="lead">把每一堂課變成修行副本。每一次準時起床、每一步踏進教室，都在回應家人的牽掛，也在成為更可靠的自己。</p>
    <ul class="w-list">
      <li>☀️ 每天四個階段：晨起啟動 → 副本挑戰 → 晚間羈絆 → 休整總結，大約 5 分鐘。</li>
      <li>👨‍👩‍👧 媽媽、爸爸、妹妹三條羈絆線，隨著你的成長一一解鎖劇情。</li>
      <li>⚡ 妹妹也是大一新生：在「兄妹」分頁看她今天的行程，週三、週四一起拚早八。</li>
      <li>🌱 沒有懲罰式的責罵：缺課會有關心、有補救機會，隨時都能重新出發。</li>
    </ul>
    <div class="form">
      <label>你的名字<input id="w-name" value="${esc(S.profile.hero)}" maxlength="12"></label>
      <div class="radio-row"><span>從哪天開始修行？</span>
        <label><input type="radio" name="w-start" value="${t}" checked> 今天 ${D.label(t)}</label>
        <label><input type="radio" name="w-start" value="${tm}"> 明天 ${D.label(tm)}</label></div>
      <p class="hint">已預先載入你 115-1 的課表（化材 1B），以及妹妹在靜宜大學食品營養學系的課表，之後都可以在「設定」修改。${HOOKS.welcomeNote ? HOOKS.welcomeNote() : '遊戲進度只存在這個瀏覽器裡，記得偶爾到「設定」匯出備份。'}</p>
    </div>
    <button class="btn primary big" data-act="start">開始修行</button>${HOOKS.welcomeExtra ? '\n    ' + HOOKS.welcomeExtra() : ''}
  </div>`;
}

// ---------------------------------------------------------------------
//  今日
// ---------------------------------------------------------------------
function bannerSpeaker(ph, d) {
  const open = MEMBERS.filter((m) => S.bonds[m].lv >= 1);
  if (!open.length) return 'mom';
  const pref = { morning: 'mom', day: 'dad', evening: 'sis', done: MEMBERS[D.diff('2026-01-01', d) % 3] }[ph] || 'mom';
  return open.includes(pref) ? pref : open[0];
}

function banner(d, ph) {
  const time = { morning: 'morning', day: 'day', evening: 'evening', done: 'night' }[ph] || 'morning';
  const ss = sessionsOn(d);
  const type = holName(d) ? `🎌 ${holName(d)}` : ss.length ? `上課日 · ${ss.length} 堂` : (D.wd(d) >= 6 ? '週末' : '今天沒有課');
  const wk = inSem(d) ? `第 ${semWeek(d)} 週` : '學期外';
  const sp = bannerSpeaker(ph, d);
  const line = sp === 'sis' ? sisLine(d, ph) : LINES.banner[ph][sp];
  const steps = [['morning', '晨起'], ['day', '副本'], ['evening', '晚間'], ['done', '總結']];
  const idx = steps.findIndex((x) => x[0] === ph);
  return `<div class="banner">
    ${scene('bedroom', { time })}
    <div class="b-hero">${actorBox()}</div>
    <div class="b-date"><div class="b-day">${D.label(d)}</div><div class="b-sub">${wk} · ${type}</div></div>
    <div class="b-say">${portrait(sp, 'smile', 'casual', 'mini')}<div class="bubble"><b>${esc(nameOf(sp))}</b>${esc(fill(line))}</div></div>
    <ol class="steps">${steps.map(([k, n], i) => `<li class="${i < idx ? 'done' : i === idx ? 'cur' : ''}">${n}</li>`).join('')}</ol>
  </div>`;
}
function actorBox() { return portrait('hero', 'happy', 'casual', 'hero-big'); }

function renderToday() {
  const t = today(), pd = playDate();
  if (S.ending && pd > semEnd()) return renderSemesterOver();
  if (pd > semEnd()) return renderSemesterOver();
  if (pd > t) return renderRestView(pd);
  const day = getDay(pd);
  const catchup = pd < t;
  const panel = { morning: morningPanel, day: questPanel, evening: eveningPanel }[day.phase] || morningPanel;
  return `<div class="today-grid">
    <section class="col-main">
      ${catchup ? catchupBar(pd) : ''}
      ${banner(pd, day.phase)}
      ${panel(pd, day)}
    </section>
    <aside class="col-side">${realTaskCard()}${statusCard(pd, day)}${sisTodayCard(pd)}${bondsMini()}${eventsCard(pd)}${weekCard(pd)}</aside>
  </div>`;
}

function catchupBar(pd) {
  const n = D.diff(pd, today());
  return `<div class="catchup card"><b>📅 補登模式</b>：你有 ${n} 天還沒結算，目前正在補登 <b>${D.label(pd)}</b>。可以照常回報；如果記不得了，也可以標記為「未回報」直接結算（未回報的課會以缺席計算）。
    <div class="row">${btn('skip:one', '把這天標記未回報並結算', false, 'ghost')} ${n > 1 ? btn('skip:all', `把到昨天為止的 ${n} 天都標記並結算`, false, 'ghost') : ''}</div></div>`;
}

function renderRestView(pd) {
  const t = today();
  const td = S.days[t];
  const tomorrow = pd;
  const ss = sessionsOn(tomorrow);
  let main = '';
  if (S.createdAt > t) {
    main = `<div class="card phase"><div class="phase-h"><span class="ph-ic">🌱</span><div><h2>修行準備中</h2><p class="sub">遊戲將從 ${D.label(S.createdAt)} 開始</p></div></div>
      <p>今晚早點睡，明天就是重新出發的第一天。目前的就寢目標是 <b>${esc(S.settings.bedtime)}</b>，可以在「設定」調整。</p></div>`;
  } else if (td && td.summary) {
    main = summaryCard(t, td.summary, true);
  }
  const prev = `<div class="card"><h3>明日預覽 · ${D.label(tomorrow)}</h3>${ss.length ? ss.map((s) => miniQuest(s, tomorrow, null)).join('') : `<p class="muted">${holName(tomorrow) ? '🎌 ' + holName(tomorrow) + '，' : ''}沒有課。記得守住作息：起床不要比平常晚超過 1.5 小時。</p>`}
    <p class="hint">就寢目標：${esc((td && td.bedtime) || S.settings.bedtime)}　·　明天的晨起階段會問你昨晚有沒有準時睡。</p></div>`;
  return `<div class="today-grid"><section class="col-main">${banner(t, 'done')}${main}${prev}</section>
    <aside class="col-side">${realTaskCard()}${statusCard(t, td || null)}${sisTodayCard(t)}${bondsMini()}${eventsCard(tomorrow)}${weekCard(t)}</aside></div>`;
}

function renderSemesterOver() {
  const e = S.ending;
  const name = e ? { perfect: '完美成長結局', steady: '穩步向前結局', regret: '留有遺憾結局' }[e.type] : '';
  return `<div class="card over">
    ${e ? storyScene('ending_' + e.type) : ''}
    <h2>🎓 這學期的修行結束了</h2>
    ${e ? `<p>你達成了 <b>${name}</b>：出勤達成率 <b>${Math.round(e.rate * 100)}%</b>、羈絆總值 <b>${e.bond}</b>、學識 <b>${e.know}</b>，學期評價 <b class="grade">${e.grade || '—'}</b>。</p>
    ${e.dadPride ? `<div class="care">${portrait('dad', 'happy', 'formal', 'mini')}<div><b>${esc(nameOf('dad'))}的認可</b><p>「這學期，我都看在眼裡。你做得很好。」</p></div></div>` : ''}
    <div class="row">${btn('replay:ending_' + e.type, '重看結局')} ${btn('tab:album', '打開紀念冊')} ${btn('tab:records', '查看紀錄')}</div>` : ''}
    <hr><h3>開始新的學期</h3>
    <p>等級、羈絆、技能、道具、紀念冊與徽章都會保留；出勤統計會從新學期重新計算。請先到「設定」更新學期開始日、週數、課表與假日。</p>
    ${btn('newsem', '開始新學期', false, 'primary')}
  </div>`;
}

function noticeList(d, day) {
  const out = [];
  if (isNewbie(d)) out.push(`🌱 新手期（開學前 3 週）：還有 ${newbieLeft(d)} 天，副本經驗 +30%。`);
  const b = postBlock(d);
  if (b) {
    out.push(`🏔️ 收假後第一週：早上的課升級為 ★★★★ 地獄副本（獎勵更高）。`);
    if (firstClassAfter(b) === d) out.push(`😮‍💨 連假後遺症：心情 −${S.bonds.dad.lv >= 2 ? '10（爸爸的收心加成：減半）' : '20'}。`);
  }
  if (day && day.sleep === 'late') out.push('🌙 昨晚熬夜：今天早上的課升級為 ★★★★ 地獄副本。');
  if (inWin(finWindow(), d)) out.push('⚔️ 期末最終決戰：副本經驗 +20%，課後複習學識加倍。');
  if (inWin(midWindow(), d)) out.push('📖 期中衝刺季：課後複習學識加倍。');
  const hb = holidayBlocks().find((x) => d >= x.announce && d < x.start && x.start >= (S.createdAt || ''));
  if (hb) out.push(`🏔️ 連假守護戰即將開始（${D.md(hb.start)}–${D.md(hb.end)} ${hb.names}）：連假每天準時起床、收假後一週全勤。`);
  return out.length ? `<ul class="notices">${out.map((x) => `<li>${x}</li>`).join('')}</ul>` : '';
}

function miniQuest(s, d, day) {
  const e = effDiff(s, d, day || { sleep: null });
  return `<div class="mq">${starHTML(e.d)}<span class="mq-t">${esc(s.start)}–${esc(s.end)}</span><span class="mq-n">${esc(s.name)}</span>
    <span class="mq-g">${portrait(s.guardian, 'smile', 'casual', 'tiny')}</span>${e.tags.filter((x) => x !== '早八' && x !== '連堂').map((x) => chip(x, 'warn')).join('')}</div>`;
}

function morningPanel(d, day) {
  const ss = sessionsOn(d);
  const isClass = ss.length > 0;
  let h = `<div class="card phase"><div class="phase-h"><span class="ph-ic">☀️</span><div><h2>晨起啟動</h2><p class="sub">${isClass ? `今天有 ${ss.length} 個副本等著你` : '今天沒有課——守住作息，也是修行'}</p></div></div>`;
  h += `<div class="q"><div class="q-t">昨晚有在 <b>${esc(day.bedtimePrev)}</b> 前睡覺嗎？</div><div class="seg">${btn('sleep:ok', '😴 有，準時睡', day.sleep === 'ok')}${btn('sleep:late', '🌙 熬夜了', day.sleep === 'late')}</div></div>`;
  if (day.sleep) {
    const hint = isClass ? '' : `<span class="hint">休息日目標：不要比平常晚超過 1.5 小時（約 ${addMin(S.settings.wake, 90)} 前）</span>`;
    h += `<div class="q"><div class="q-t">今天起床狀況？${hint}</div><div class="seg">${btn('wake:ok', '⏰ 準時起床', day.wake === 'ok')}${btn('wake:snooze', '🛌 賴床但有起來', day.wake === 'snooze')}${btn('wake:over', '💤 睡過頭', day.wake === 'over')}</div>`;
    if ((day.wake === 'snooze' || day.wake === 'over') && !day.supply && S.items.supply > 0) h += `<div class="row">${btn('supply', `🧺 使用居家補給包（剩 ${S.items.supply}）抵消這次賴床`, false, 'ghost')}</div>`;
    if (day.supply) h += `<p class="ok-note">🧺 已使用居家補給包：這次賴床不扣自律，早起紀錄不中斷。</p>`;
    h += `</div>`;
  }
  const open = MEMBERS.filter((m) => S.bonds[m].lv >= 1);
  if (open.length) {
    h += `<div class="q"><div class="q-t">啟用家人的羈絆 buff <span class="hint">一天最多 ${maxBuffs()} 位${maxBuffs() > 1 ? '（家人祈願：效果 +10%）' : ''}</span></div><div class="buffs">`;
    h += open.map((m) => {
      const on = day.buffs.includes(m);
      const b = MEMBER[m].buff;
      const desc = m === 'mom' && S.bonds.mom.lv >= 4 ? '今天的早八課出席後，自律 +10（效果翻倍）；起床失敗不扣自律。' : b.desc;
      return `<button class="buff${on ? ' on' : ''}" data-act="buff:${m}" style="--c:${MEMBER[m].hex}">${portrait(m, on ? 'happy' : 'smile', 'casual', 'mini')}<div><b>${b.icon} ${b.name}</b><small>${esc(nameOf(m))} · ${desc}</small></div></button>`;
    }).join('');
    h += `</div></div>`;
  }
  if (isClass) h += `<div class="q"><div class="q-t">今日副本預覽</div>${ss.map((s) => miniQuest(s, d, day)).join('')}</div>`;
  h += noticeList(d, day);
  const ready = day.sleep && day.wake;
  h += `<div class="actions">${btn('begin', isClass ? '⚔️ 出發！開始今天' : '🌙 記錄作息，前往晚間', false, 'primary big', ready ? '' : 'disabled')}${ready ? '' : '<span class="hint">先回答上面兩題</span>'}</div></div>`;
  return h;
}
function addMin(t, m) { const v = tmin(t) + m; return `${pad(Math.floor(v / 60) % 24)}:${pad(v % 60)}`; }

function rewardChips(it) {
  const out = [];
  if (it.exp) out.push(chip(`經驗 +${it.exp}`, 'exp'));
  if (it.know) out.push(chip(`學識 +${it.know}`, 'know'));
  if (it.aff) out.push(chip(`${esc(nameOf(it.s.guardian))}好感 ${signed(it.aff)}`, it.aff > 0 ? 'aff' : 'neg'));
  if (it.grit < 0) out.push(chip(`堅毅 ${signed(it.grit)}`, 'neg'));
  return out.join('');
}

function questCard(it, d, day) {
  const s = it.s, o = it.o;
  const st = o ? OUT[o] : null;
  let body = '';
  if (!o) {
    body = `<div class="rep">${['perfect', 'late', 'left', 'absent', 'leave', 'cancel'].map((k) => `<button class="rb ${OUT[k].cls}" data-act="rep:${s.id}:${k}">${OUT[k].short}</button>`).join('')}</div>`;
  } else {
    let extra = '';
    if (o === 'absent') {
      if (it.rep.remedied) extra += chip('🧵 已完成補救任務', 'ok');
      else if (remedyLeft(d) > 0) extra += btn(`remedy:${s.id}`, `🧵 補救任務（本週剩 ${remedyLeft(d)} 次）`, false, 'ghost sm');
      else extra += `<span class="hint">本週補救次數已用完</span>`;
    }
    if (o === 'left') {
      if (it.rep.medal) extra += chip('🎖️ 已使用堅毅勳章', 'ok');
      else if (S.items.medal > 0) extra += btn(`medal:${s.id}`, `🎖️ 使用堅毅勳章（剩 ${S.items.medal}）`, false, 'ghost sm');
    }
    body = `<div class="res"><span class="st ${st.cls}">${st.full}</span>${rewardChips(it)}${extra}<button class="link" data-act="unrep:${s.id}">修改</button></div>`;
    if (it.why.length) body += `<div class="why">${it.why.map(esc).join('　')}</div>`;
  }
  return `<div class="quest d${it.d}${o ? ' done ' + st.cls : ''}">
    <div class="qh"><span class="qt">${esc(s.start)}–${esc(s.end)}</span>${starHTML(it.d)}<span class="qd">${DIFF[it.d].name}</span></div>
    <div class="qn">${esc(s.name)} ${s.room ? `<span class="room">${esc(s.room)}</span>` : ''}</div>
    <div class="qm">${it.tags.map((x) => chip(x, /熬夜|收假/.test(x) ? 'warn' : '')).join('')}${early8(s) && sisEarly(d) ? chip('⚡ 兄妹同步早八', 'sync') : ''}<span class="guard">${portrait(s.guardian, 'smile', 'casual', 'tiny')}${esc(nameOf(s.guardian))}守護</span>${s.note ? `<span class="note">${esc(s.note)}</span>` : ''}</div>
    ${(() => { const ov = sisOverlap(s, d); return ov.length ? `<div class="sis-ov">${portrait('sis', 'smile', 'casual', 'tiny')} 同一時段，${esc(nameOf('sis'))}在${ov[0].room ? esc(ov[0].room) + ' ' : '教室'}上「${esc(ov[0].name)}」</div>` : ''; })()}
    ${body}
  </div>`;
}

function pendingCard(R, title = '今日累積（晚間領取）') {
  return `<div class="pending"><div class="p-t">${title}</div><div class="p-g">
    <div><b>${R.exp}</b><span>經驗</span></div><div><b>${R.know}</b><span>學識點</span></div>
    <div><b>${signed(R.discEff)}</b><span>自律</span></div><div><b>${signed(R.gritEff)}</b><span>堅毅</span></div>
    ${MEMBERS.map((m) => `<div><b>${signed(R.aff[m] || 0)}</b><span>${esc(nameOf(m))}</span></div>`).join('')}
  </div>${R.notes.length ? `<ul class="notes">${R.notes.map((n) => `<li>${esc(n)}</li>`).join('')}</ul>` : ''}</div>`;
}

function questPanel(d, day) {
  const R = computeDay(d, day);
  const total = R.list.length, done = total - R.pending;
  const maxD = R.list.reduce((a, x) => Math.max(a, x.d), 1);
  const nextQ = R.list.find((x) => !x.o);
  let h = `<div class="card phase"><div class="cls-banner">${scene('classroom', { level: maxD, par: 'xMidYMin slice', text: nextQ ? `下一堂：${nextQ.s.name}` : '今天的副本都回報完了' })}</div><div class="phase-h"><span class="ph-ic">⚔️</span><div><h2>副本挑戰</h2><p class="sub">依真實出勤回報每一堂課（已回報 ${done}/${total}）。這是只對自己誠實才有意義的遊戲。</p></div></div>`;
  h += `<div class="quests">${R.list.map((it) => questCard(it, d, day)).join('')}</div>`;
  h += pendingCard(R);
  h += `<div class="actions">`;
  if (S.items.candy > 0 && !day.candy) h += btn('candy', `🍬 吃元氣糖果（剩 ${S.items.candy}）`, false, 'ghost');
  if (!day.restart) h += btn('restart', '↺ 隨時重啟：從下一堂課重新出發', false, 'ghost');
  h += btn('toEvening', '🌙 前往晚間羈絆', false, 'primary big');
  h += `</div></div>`;
  return h;
}

function eveningPanel(d, day) {
  const R = computeDay(d, day);
  const open = MEMBERS.filter((m) => S.bonds[m].lv >= 1);
  const isClass = R.list.length > 0;
  let h = `<div class="card phase"><div class="phase-h"><span class="ph-ic">🌙</span><div><h2>晚間羈絆</h2><p class="sub">${isClass ? `今天出席 ${R.attended}/${R.counted || R.list.length} 堂${R.perfectAll ? ' · ☀️ 全日完美通關！' : R.fullAttend ? ' · 全日出席' : ''}` : '休息日的晚上，跟家人說說話吧'}</p></div></div>`;
  if (R.pending) h += `<p class="warn-note">還有 ${R.pending} 堂課沒有回報；結算時會以「未回報」計算（等同缺席）。${btn('toDay', '回去回報', false, 'link')}</p>`;
  // 妹妹今天的分享（兄妹同步）
  const ssis = sisSessionsOn(d);
  const share = ssis.length ? dpick((SIS_TALK[ssis[ssis.length - 1].id] || {}).a || [], d + ssis[ssis.length - 1].id + 'a') : sisShareLine(d);
  h += `<div class="q sis-eve">${portrait('sis', 'happy', 'casual', 'mini')}<div><b>📱 ${esc(nameOf('sis'))}今天的分享</b><p>${esc(fill(share))}</p>
    ${R.sync ? '<p class="sync-l">⚡ 今天兄妹同步早八達成！（經驗 +10）</p>' : R.syncPossible ? '<p class="tiny-note">今天是同步早八日：回報準時出席早八就能同步。</p>' : ''}
    <small>${ssis.length ? `她今天上了 ${ssis.length} 堂課：${ssis.map((g) => esc(shortName(g))).join('、')}` : '她今天沒有課'}　${btn('tab:sib', '看兄妹分頁', false, 'link')}</small></div></div>`;
  // 家人互動
  h += `<div class="q"><div class="q-t">選一位家人互動${R.perfectAll ? ' <span class="hint">全日完美：解鎖特別互動，好感 +3</span>' : ''}</div>`;
  if (day.inter) {
    const m = day.inter.who;
    h += `<div class="inter-done">${portrait(m, 'happy', 'casual', 'mini')}<div><b>${esc(nameOf(m))} · ${LINES.interType[day.inter.type]}</b><p>${esc(fill(day.inter.line))}</p></div></div>`;
  } else {
    h += `<div class="who">${open.map((m) => `<button class="who-b${UI.interWho === m ? ' on' : ''}" data-act="iwho:${m}" style="--c:${MEMBER[m].hex}">${portrait(m, 'smile', 'casual', 'mini')}<span>${esc(nameOf(m))}</span></button>`).join('')}</div>`;
    if (UI.interWho && open.includes(UI.interWho)) h += `<div class="seg">${Object.entries(LINES.interType).map(([k, n]) => btn(`inter:${UI.interWho}:${k}`, n)).join('')}</div>`;
  }
  h += `</div>`;
  // 複習與就寢
  const k2 = inWin(midWindow(), d) || inWin(finWindow(), d);
  h += `<div class="q"><div class="q-t">課後複習任務</div>${btn('review', day.review ? `✅ 今天有做課後複習（學識點 +${k2 ? 10 : 5}）` : `📖 我今天有做課後複習（20 分鐘以上）${k2 ? ' · 加倍中' : ''}`, day.review, 'wide')}</div>`;
  h += `<div class="q"><div class="q-t">設定今晚的就寢時間</div><label class="time-l"><input type="time" data-bind="bedtime" value="${esc(day.bedtime)}"> <span class="hint">明天早上會問你有沒有做到</span></label></div>`;
  h += pendingCard(R, '今日獎勵（按下領取後入帳）');
  h += `<div class="actions">${isClass ? btn('toDay', '← 回到副本修改', false, 'ghost') : btn('toMorning', '← 修改晨起回報', false, 'ghost')}${btn('settle', '✨ 領取獎勵並結束今天', false, 'primary big')}</div></div>`;
  return h;
}

function summaryCard(d, sm, compact) {
  const att = sm.items.filter((i) => i.o !== 'cancel');
  const ok = att.filter((i) => i.o === 'perfect' || i.o === 'late').length;
  return `<div class="card phase"><div class="phase-h"><span class="ph-ic">✨</span><div><h2>休整總結 · ${D.label(d)}</h2><p class="sub">${att.length ? `出席 ${ok}/${att.length} 堂${sm.perfect ? ' · ☀️ 全日完美通關' : sm.full ? ' · 全日出席' : ''}` : '休息日'}</p></div></div>
    ${att.length ? `<div class="sum-items">${sm.items.map((i) => `<span class="st ${OUT[i.o].cls}">${esc(i.name)}：${OUT[i.o].short}${i.remedied ? '（已補救）' : ''}</span>`).join('')}</div>` : ''}
    <div class="p-g sum-g"><div><b>+${sm.exp}</b><span>經驗</span></div><div><b>+${sm.know}</b><span>學識點</span></div><div><b>${signed(sm.disc)}</b><span>自律</span></div><div><b>${signed(sm.grit)}</b><span>堅毅</span></div>
    ${MEMBERS.map((m) => `<div><b>${signed(sm.aff[m] || 0)}</b><span>${esc(nameOf(m))}</span></div>`).join('')}</div>
    ${compact ? `<p class="hint">今天已經結束。好好休息，明天見。</p>` : ''}</div>`;
}

// ---------- 側欄 ----------
function statusCard(d, day) {
  const R = day && !day.settled ? computeDay(d, day) : null;
  const kv = knowValue();
  return `<div class="card side">
    <h3>勇者狀態</h3>
    <div class="stat"><span>自律</span>${bar(S.player.disc, 100, 'disc')}<b>${Math.round(S.player.disc)}</b></div>
    <div class="stat"><span>堅毅</span>${bar(S.player.grit, 100, 'grit')}<b>${Math.round(S.player.grit)}</b></div>
    <div class="stat"><span>學識</span>${bar(kv, 100, 'know')}<b>${kv}</b></div>
    <p class="tiny-note">學識點 ${S.player.knowPts} / 學期目標 ${knowTarget()}</p>
    ${R ? `<div class="stat"><span>心情</span>${bar(R.mood, 100, 'mood')}<b>${R.mood}</b></div><div class="stat"><span>疲勞</span>${bar(R.fatigue, 100, 'fat')}<b>${R.fatigue}</b></div>
    ${R.mood >= 80 && (R.fatigue < 70 || day.candy) ? '<p class="tiny-note good">😊 好心情：副本經驗 +10%</p>' : R.fatigue >= 70 ? '<p class="tiny-note">😮‍💨 有點累了：好心情加成暫停，可以吃顆元氣糖果。</p>' : ''}` : ''}
    <div class="streaks"><div><b>${S.streak.attend}</b><span>連續全勤</span></div><div><b>${S.streak.wake}</b><span>早起連續</span></div><div><b>${S.streak.noMiss}</b><span>無缺課天數</span></div></div>
    <div class="items">${Object.entries(ITEMS).map(([k, it]) => `<span title="${esc(it.desc)}">${it.icon}×${S.items[k]}</span>`).join('')}<span title="每週 2 次">🧵補救 ${remedyLeft(d)}/2</span></div>
  </div>`;
}

function bondsMini() {
  return `<div class="card side"><h3>家人羈絆</h3>${MEMBERS.map((m) => {
    const b = S.bonds[m];
    return `<button class="bm" data-act="tab:bonds">${portrait(m, b.lv >= 3 ? 'happy' : 'smile', 'casual', 'tiny')}<span class="bm-n">${esc(nameOf(m))}</span>${bar(b.aff, 100, 'aff')}<span class="bm-v">${b.lv ? 'Lv' + b.lv : '🔒'} · ${affShow(b.aff)}</span></button>`;
  }).join('')}<p class="tiny-note">羈絆總值 ${bondTotal()} / 300</p></div>`;
}

function eventsCard(d) {
  const out = [];
  if (isNewbie(d)) out.push(`<li>🌱 <b>新手期</b>：剩 ${newbieLeft(d)} 天，經驗 +30%</li>`);
  holidayBlocks().forEach((b) => {
    const st = holidayStatus(b);
    if (st.state === 'missed' || st.state === 'won' || st.state === 'lost') return;
    if (st.state === 'future') { if (D.diff(d, b.start) <= 21) out.push(`<li>🏔️ <b>連假守護戰</b>：${D.md(b.start)}–${D.md(b.end)}（${b.names}），${D.diff(d, b.announce)} 天後開啟</li>`); return; }
    const p = st.state === 'announce' ? `${D.diff(d, b.start)} 天後連假開始` : st.state === 'during' ? `連假中：準時起床 ${st.wakeOk}/${st.total}` : `收假週：${st.postFail ? '已有缺課' : '目前全勤'}（到 ${D.md(b.postEnd)}）`;
    out.push(`<li>🏔️ <b>連假守護戰</b>（${b.names}）：${p}${st.failed ? ' · 本次未達成' : ''}</li>`);
  });
  const ms = midStatus();
  if (ms.state === 'active') out.push(`<li>📖 <b>期中衝刺季</b>：成長能量 ${ms.energy}/10，複習學識加倍</li>`);
  const fw = finWindow();
  if (inWin(fw, d)) {
    let att = 0, tot = 0, rev = 0;
    daysRange(fw.start, fw.end).forEach((x) => { const sm = S.days[x] && S.days[x].summary; if (!sm) return; sm.items.forEach((i) => { if (i.o === 'cancel') return; tot++; if (i.o === 'perfect' || i.o === 'late') att++; }); if (sm.review) rev++; });
    out.push(`<li>⚔️ <b>期末最終決戰</b>：剩 ${D.diff(d, fw.end) + 1} 天，經驗 +20%<br><small>決戰成績：出席 ${att}/${tot} 堂、複習 ${rev} 天</small></li>`);
  }
  else if (d < fw.start && D.diff(d, fw.start) <= 28) out.push(`<li>⚔️ 期末最終決戰：${D.diff(d, fw.start)} 天後開始</li>`);
  return out.length ? `<div class="card side"><h3>限時活動</h3><ul class="ev">${out.join('')}</ul></div>` : '';
}

function weekCard(d) {
  if (S.player.level < 3) return `<div class="card side"><h3>週常挑戰</h3><p class="tiny-note">🔒 玩家 Lv3 解鎖（目前 Lv${S.player.level}）</p></div>`;
  const st = weekStatus(D.monday(d));
  const discDone = st.early > 0 && st.earlyOk === st.early;
  return `<div class="card side"><h3>本週挑戰</h3>
    <div class="wk"><b>自律</b>：早八出席 ${st.earlyOk}/${st.early}${discDone ? ' ✅' : ''}<small>獎勵：技能點 +1、全員好感 +5</small></div>
    <div class="wk"><b>堅毅</b>：中途離開 ${st.left} 次、整天缺席 ${st.fullAbsentDays} 天${st.left === 0 && st.fullAbsentDays === 0 ? ' · 保持中' : ' · 本週未達成'}<small>獎勵：堅毅 +10、${esc(nameOf('dad'))}好感 +8</small></div>
  </div>`;
}

// ---------------------------------------------------------------------
//  兄妹：妹妹的課表、今日行程、即時動態、同步早八
// ---------------------------------------------------------------------
const sisShort = () => (!S.profile.sisSchool || S.profile.sisSchool === SIS_INFO.school + ' ' + SIS_INFO.dept ? '靜宜 食營 大一' : S.profile.sisSchool);
const OICON = { perfect: '✓', late: '⏱', left: '↩', absent: '✗', leave: '📝', cancel: '⊘', none: '？' };
function heroStatusOf(d, s) {
  const day = S.days[d];
  if (!day) return '';
  if (day.summary) { const it = day.summary.items.find((i) => i.id === s.id); return it ? it.o : ''; }
  return (day.reports[s.id] && day.reports[s.id].o) || '';
}
function sisStateText(st, d) {
  const c = st.cur, nx = st.next;
  switch (st.state) {
    case 'class': return `${c.icon || '📚'} 正在上「${esc(c.name)}」${c.room ? `（${esc(c.room)}）` : ''}・還有 ${st.left} 分鐘下課`;
    case 'before': return `☀️ 還沒上課，${esc(nx.start)} 有「${esc(nx.name)}」`;
    case 'break': return `☕ 下課休息中，${st.until} 分鐘後上「${esc(nx.name)}」`;
    case 'lunch': return `🍱 午餐時間，${esc(nx.start)} 上「${esc(nx.name)}」`;
    case 'done': return `🏠 今天的 ${st.list.length} 堂課都上完了`;
    case 'weekend': return '🛋️ 週末，沒有課';
    case 'holiday': return `🎌 ${esc(holName(d))}，放假`;
    default: return '📚 今天沒有課';
  }
}
function heroStateText(d, m) {
  const ss = sessionsOn(d);
  if (!ss.length) return holName(d) ? `🎌 ${esc(holName(d))}，放假` : D.wd(d) >= 6 ? '🛋️ 週末，沒有課' : '📚 今天沒有課';
  const cur = ss.find((s) => m >= tmin(s.start) && m < tmin(s.end));
  const nx = ss.find((s) => tmin(s.start) > m);
  if (cur) return `⚔️ 副本進行中「${esc(cur.name)}」・還有 ${tmin(cur.end) - m} 分鐘`;
  if (nx) return `🎒 下一堂 ${esc(nx.start)}「${esc(nx.name)}」${nx.room ? `（${esc(nx.room)}）` : ''}`;
  return `🌙 今天的 ${ss.length} 堂課都結束了`;
}
const daySummaryText = (list) => (list.length ? list.map((s) => `${esc(s.start)} ${esc(shortName(s))}`).join('、') : '沒有課');

function sisFeed(d, live, m) {
  const out = [];
  sisSessionsOn(d).forEach((g) => {
    const t = SIS_TALK[g.id] || {};
    const s0 = tmin(g.start), e0 = tmin(g.end);
    [['b', s0 - 10], ['d', Math.round((s0 + e0) / 2)], ['a', e0 + 5]].forEach(([k, at]) => {
      const arr = t[k] || [];
      if (arr.length) out.push({ at, k, g, text: dpick(arr, d + g.id + k) });
    });
  });
  if (!out.length) {
    const pool = holName(d) ? SIS_FREE.holiday : D.wd(d) >= 6 ? SIS_FREE.weekend : SIS_FREE.weekday;
    out.push({ at: 600, k: 'f', g: null, text: dpick(pool, d) });
  }
  return out.sort((a, b) => a.at - b.at).map((x) => ({ ...x, future: live && x.at > m }));
}
const hhmm = (m) => `${pad(Math.floor(Math.max(0, m) / 60))}:${pad(Math.max(0, m) % 60)}`;

function tlPos(t) { return clamp((tmin(t) - 480) / 6, 0, 100); }
function dualTimeline(d, live, m) {
  const mine = sessionsOn(d), hers = sisSessionsOn(d);
  const blk = (s, cls, label, tip) => `<div class="tl-b ${cls}" style="left:${tlPos(s.start).toFixed(2)}%;width:${Math.max(3, tlPos(s.end) - tlPos(s.start)).toFixed(2)}%" title="${esc(tip)}">${label}</div>`;
  const meB = mine.map((s) => {
    const o = heroStatusOf(d, s);
    const ov = sisOverlap(s, d).length ? ' ov' : '';
    const sync = early8(s) && sisEarly(d) ? '⚡' : '';
    return blk(s, `mine${o ? ' o-' + OUT[o].cls : ''}${ov}`, `${sync}${esc(shortName(s))}${o ? ` <i>${OICON[o]}</i>` : ''}`, `${s.start}–${s.end} ${s.name}${o ? '：' + OUT[o].short : ''}`);
  }).join('');
  const herB = hers.map((g) => blk(g, `hers${mine.some((s) => overlapMin(s, g) >= 30) ? ' ov' : ''}`, `${g.icon || ''}${esc(shortName(g))}`, `${g.start}–${g.end} ${g.name}${g.room ? '（' + g.room + '）' : ''}`)).join('');
  const ticks = [8, 10, 12, 14, 16, 18].map((h) => `<span style="left:${(h - 8) * 10}%">${h}</span>`).join('');
  const now = live && m >= 480 && m <= 1080 ? `<i class="tl-now" style="left:${((m - 480) / 6).toFixed(2)}%" title="現在 ${hhmm(m)}"></i>` : '';
  return `<div class="tl">
    <div class="tl-row"><span class="tl-who">${portrait('hero', 'smile', 'casual', 'tiny')}我</span><div class="tl-lane">${meB || '<em>沒有課</em>'}${now}</div></div>
    <div class="tl-row"><span class="tl-who">${portrait('sis', 'smile', 'casual', 'tiny')}${esc(nameOf('sis'))}</span><div class="tl-lane">${herB || '<em>沒有課</em>'}${now}</div></div>
    <div class="tl-row"><span class="tl-who"></span><div class="tl-ticks">${ticks}</div></div>
  </div>`;
}

function weekGrid(mon) {
  const days = [0, 1, 2, 3, 4].map((i) => D.add(mon, i));
  const col = (d) => {
    const mine = sessionsOn(d), hers = sisSessionsOn(d);
    const b = (s, who) => {
      const top = clamp((tmin(s.start) - 480) / 6, 0, 100), h = Math.max(4, clamp((tmin(s.end) - 480) / 6, 0, 100) - top);
      const o = who === 'me' ? heroStatusOf(d, s) : '';
      return `<div class="wg-b ${who === 'me' ? 'mine' : 'hers'}${o ? ' o-' + OUT[o].cls : ''}" style="top:${top.toFixed(2)}%;height:${h.toFixed(2)}%" title="${esc(`${s.start}–${s.end} ${s.name}`)}">${who === 'her' && s.icon ? `<i>${s.icon}</i>` : ''}${esc(shortName(s))}</div>`;
    };
    const sync = sisEarly(d) && mine.some(early8) ? `<em class="wg-sync" title="兄妹同步早八">${S.syncDays.includes(d) ? '✅' : '⚡'}</em>` : '';
    const hol = holName(d) ? `<div class="wg-hol">🎌 ${esc(holName(d))}</div>` : '';
    return `<div class="wg-col${d === today() ? ' now' : ''}"><div class="wg-h">週${'一二三四五'[D.wd(d) - 1]}<small>${D.md(d)}</small>${sync}</div>
      <div class="wg-body">${hol}<div class="wg-lane mine">${mine.map((s) => b(s, 'me')).join('')}</div><div class="wg-lane hers">${hers.map((g) => b(g, 'her')).join('')}</div></div></div>`;
  };
  return `<div class="wg"><div class="wg-axis"><div class="wg-h"></div><div class="wg-body">${[8, 10, 12, 14, 16, 18].map((h) => `<span style="top:${(h - 8) * 10}%">${h}</span>`).join('')}</div></div>${days.map(col).join('')}</div>`;
}

function syncCard(d) {
  const n = S.counters.sync || 0;
  const mon = D.monday(d);
  const wk = [3, 4].map((w) => D.add(mon, w - 1)).filter((x) => sisEarly(x) && sessionsOn(x).some(early8));
  const marks = wk.map((x) => {
    const sm = S.days[x] && S.days[x].summary;
    const st = S.syncDays.includes(x) ? '✅ 同步' : sm ? '— 這次沒有' : '⏳ 等你出席';
    return `<span class="sy-d">${D.label(x)}：${st}</span>`;
  }).join('');
  const weeks = Object.entries(S.sibWeekly || {}).filter(([, v]) => v.mine || v.hers).sort((a, b) => (a[0] < b[0] ? 1 : -1)).slice(0, 4);
  return `<div class="card"><h3>⚡ 兄妹同步早八</h3>
    <p>週三、週四你們都是早八。你準時（或遲到但有到）出席自己的早八，就算同步成功：經驗 +10、${esc(nameOf('sis'))}好感提升；同一週同步 2 次可得徽章「並肩作戰」。</p>
    <div class="sy-row"><div class="sy-big"><b>${n}</b><span>累積同步</span></div><div class="prog">${bar(Math.min(n, 10), 10, 'aff')}<span>${Math.min(n, 10)}/10 → 徽章「兄妹早八同盟」</span></div></div>
    ${marks ? `<div class="sy-week">本週：${marks}</div>` : ''}
    ${weeks.length ? `<h4>兄妹週報</h4><ul class="sib-wk">${weeks.map(([k, v]) => `<li><span>${D.md(k)} 週</span>你出席 ${v.mineOk}/${v.mine} 堂・${esc(nameOf('sis'))} ${v.hers} 堂課・同步 ${v.sync} 次</li>`).join('')}</ul>` : '<p class="tiny-note">每週日結算時，會收到一份兄妹週報。</p>'}
  </div>`;
}

function parallelCard() {
  const mine = S.schedule, hers = S.sisSchedule || [];
  const K = [['英文', '🌐 都在修英文（一）'], ['人工智慧', '🤖 都有 AI 的課'], ['大學', '🎓 大一的入門課'], ['普通', '🔬「普通」系列基礎科學']];
  const rows = K.map(([k, label]) => {
    const a = mine.filter((c) => c.name.includes(k)), b = hers.filter((c) => c.name.includes(k));
    return a.length && b.length ? `<li><b>${label}</b><span>你：${a.map((c) => esc(c.name)).join('、')}</span><span>${esc(nameOf('sis'))}：${b.map((c) => esc(c.name)).join('、')}</span></li>` : '';
  }).join('');
  let ov = 0;
  for (let w = 1; w <= 5; w++) mine.filter((c) => Number(c.day) === w).forEach((c) => hers.filter((g) => Number(g.day) === w).forEach((g) => { ov += overlapMin(c, g) * (c.parity && c.parity !== 'all' ? 0.5 : 1); }));
  return `<div class="card"><h3>🪐 平行宇宙的課</h3>${rows ? `<ul class="para">${rows}</ul>` : ''}<p class="tiny-note">每週大約有 ${r1(ov / 60)} 小時，你們在同一個時間、不同的教室裡一起上課。</p></div>`;
}

function renderSibling() {
  const t = today();
  const d = UI.sibDate || t;
  const live = d === t, m = nowMinutes();
  const st = sisStatus(d, live ? m : -1);
  const sname = esc(nameOf('sis'));
  const syncToday = sisEarly(d) && sessionsOn(d).some(early8);
  const head = `<div class="card sib-head">
    <div class="sh-pair"><div class="sh-av">${portrait('hero', 'happy', 'casual')}<b>${esc(S.profile.hero)}</b><small>淡江 化材 大一</small></div>
      <div class="sh-mid">⚡<small>一起奮鬥的<br>大一上學期</small></div>
      <div class="sh-av">${portrait('sis', 'happy', 'casual')}<b>${sname}</b><small>${esc(sisShort())}</small></div></div>
    <div class="sh-live">${live ? `<p><span class="dot"></span><b>現在 ${hhmm(m)}</b></p>
      <p class="me-l">你：${heroStateText(d, m)}</p><p class="her-l">${sname}：${sisStateText(st, d)}</p>`
      : `<p><b>${D.label(d)}</b></p><p class="me-l">你：${daySummaryText(sessionsOn(d))}</p><p class="her-l">${sname}：${daySummaryText(st.list)}</p>`}
      ${syncToday ? `<p class="sync-l">⚡ 這天是兄妹同步早八日${S.syncDays.includes(d) ? '：已同步 ✅' : '：準時出席你的早八就能同步'}</p>` : ''}</div>
  </div>`;
  const nav = `<div class="row sib-nav">${btn('sibday:-1', '‹ 前一天', false, 'ghost sm')}${live ? '' : btn('sibday:0', '回到今天', false, 'ghost sm')}${btn('sibday:1', '後一天 ›', false, 'ghost sm')}</div>`;
  const tl = `<div class="card"><h3>${live ? '今天的我們' : '這一天的我們'} · ${D.label(d)}</h3>${nav}${dualTimeline(d, live, m)}
    <p class="tiny-note">⚡ 兄妹同步早八　· 有色外框＝同一時段都在上課　· 你的課會標上回報結果（✓ 準時、⏱ 遲到、✗ 缺席）</p></div>`;
  const feed = sisFeed(d, live, m);
  const fd = `<div class="card"><h3>📱 ${sname}的動態</h3><ul class="feed">${feed.map((x) => x.future
    ? `<li class="fut"><span>${hhmm(x.at)}</span>⏳ ${x.g ? `${esc(x.g.name)}${x.k === 'a' ? '下課後' : x.k === 'b' ? '上課前' : '上課中'}` : ''}的動態，到時候揭曉</li>`
    : `<li><span>${hhmm(x.at)}</span>${x.g ? `<em>${x.g.icon || ''} ${esc(shortName(x.g))}</em>` : ''}${esc(fill(x.text))}</li>`).join('')}</ul></div>`;
  const mon = D.monday(d);
  const wg = `<div class="card"><h3>本週雙人課表 · ${D.md(mon)}–${D.md(D.add(mon, 4))}</h3><div class="wg-leg"><span class="lg mine">我（淡江化材）</span><span class="lg hers">${sname}（靜宜食營）</span><span>⚡ 同步早八</span></div>${weekGrid(mon)}</div>`;
  const list = `<div class="card"><h3>${sname}的課表</h3><table class="tbl sis-tbl"><tr><th>星期</th><th>時間</th><th>課程</th><th>教室</th></tr>${(S.sisSchedule || []).slice().sort((a, b) => a.day - b.day || tmin(a.start) - tmin(b.start)).map((g) => `<tr><td>${D.wname(g.day)}</td><td>${esc(g.start)}–${esc(g.end)}</td><td>${g.icon || ''} ${esc(g.name)}${g.note ? `<small>${esc(g.note)}</small>` : ''}</td><td>${esc(g.room || '')}</td></tr>`).join('')}</table>
    <p class="hint">課表有異動，可以到「設定 → ${sname}的課表」修改。${btn('tab:settings', '前往設定', false, 'link')}</p></div>`;
  return `<div class="stack">${head}${tl}${fd}${wg}${syncCard(d)}${parallelCard()}${list}</div>`;
}

// 今日側欄：妹妹的今天
function sisTodayCard(d) {
  const live = d === today(), m = nowMinutes();
  const st = sisStatus(d, live ? m : -1);
  const syncToday = sisEarly(d) && sessionsOn(d).some(early8);
  const items = st.list.map((g) => {
    const cls = live ? (m >= tmin(g.end) ? 'past' : m >= tmin(g.start) ? 'cur' : '') : '';
    return `<li class="${cls}"><span>${esc(g.start)}</span>${g.icon || ''} ${esc(g.name)}</li>`;
  }).join('');
  return `<div class="card side sis-card"><h3>📱 ${esc(nameOf('sis'))}的今天</h3>
    <div class="sc-row">${portrait('sis', 'happy', 'casual', 'mini')}<p>${live ? sisStateText(st, d) : daySummaryText(st.list)}</p></div>
    ${items ? `<ul class="sc-list">${items}</ul>` : ''}
    ${syncToday ? `<p class="sync-l">⚡ 今天兄妹同步早八${S.syncDays.includes(d) ? '：已同步 ✅' : '！'}</p>` : ''}
    ${btn('tab:sib', '打開兄妹分頁 →', false, 'link')}</div>`;
}

// 現實任務：體育期中退選提醒（淡江 115-1：12/7 12:30 – 12/11 16:30）
const PE_DROP = { open: '2026-12-07', close: '2026-12-11' };
function realTaskCard() {
  const T = S.tasks && S.tasks.pe;
  const t = today();
  if (!T || T.done || T.hidden || t > PE_DROP.close) return '';
  const open = t >= PE_DROP.open;
  return `<div class="card side real-task${open ? ' hot' : ''}"><h3>📝 現實任務：體育期中退選</h3>
    <p>${open ? '<b>退選期間開放中！</b>' : `還有 ${D.diff(t, PE_DROP.open)} 天開放。`}淡江 115-1 期中退選：<b>12/7（一）12:30 – 12/11（五）16:30</b>。記得到選課系統完成「男、女生體育」的期中退選（實際時間以學校公告為準）。</p>
    <div class="row">${btn('petask:done', '✅ 我已完成退選', false, 'primary sm')}${btn('petask:hide', '先隱藏', false, 'link')}</div></div>`;
}

// 依妹妹當天的課，換上她的即時台詞
function sisLine(d, ph) {
  const ss = sisSessionsOn(d);
  if (ph === 'morning') {
    if (sisEarly(d) && sessionsOn(d).some(early8)) return '哥！我們今天都是早八，比賽誰先到教室！';
    if (sisEarly(d)) return `我今天早八（${ss[0].name}），哥你可以多睡一下，羨慕！`;
    if (ss.length) return `哥起床了沒～我今天 ${ss[0].start} 才有課！`;
  } else if (ph === 'day' && ss.length) {
    const m = d === today() ? nowMinutes() : 600;
    const st = sisStatus(d, m);
    if (st.cur) return `我在上「${st.cur.name}」，哥也要認真上課喔！`;
    if (st.next) return `我等一下 ${st.next.start} 有「${st.next.name}」，一起加油！`;
    return '我今天的課都上完了！哥加油～';
  } else if ((ph === 'evening' || ph === 'done') && ss.length) {
    const g = ss[ss.length - 1];
    return dpick((SIS_TALK[g.id] || {}).a || [], d + g.id + 'a') || LINES.banner[ph].sis;
  }
  return LINES.banner[ph].sis;
}

// ---------------------------------------------------------------------
//  羈絆
// ---------------------------------------------------------------------
function renderBonds() {
  const hero = `<div class="card bond-card hero-card"><div class="bc-head"><div class="bc-av">${portrait('hero', 'happy', 'casual')}</div>
    <div><h2>${esc(S.profile.hero)} <small>見習勇者 · 主角</small></h2><p>透過一學期的修行，成長為可靠、自律，能讓家人安心驕傲的人。</p>
    <div class="gallery">${['smile', 'concern', 'happy'].map((e) => `<figure>${avatarSVG('hero', e, 'casual')}<figcaption>${{ smile: '微笑', concern: '關心', happy: '開心' }[e]}</figcaption></figure>`).join('')}<figure>${avatarSVG('hero', 'smile', 'formal')}<figcaption>正式</figcaption></figure></div></div></div></div>`;
  const cards = MEMBERS.map((m) => {
    const b = S.bonds[m], M = MEMBER[m];
    const open = lineOpen(m);
    const nextLv = b.lv + 1;
    let next = '';
    if (!open) next = `🔒 玩家 Lv${M.open} 時開啟這條羈絆線（目前 Lv${S.player.level}）。好感會先累積著。`;
    else if (b.lv >= 4) next = '💞 羈絆已達最高等級。';
    else {
      const needAff = BOND_THRESH[nextLv];
      const needLv = nextLv === 2 ? 4 : 5;
      next = `下一級 Lv${nextLv}「${BOND_PERKS[m][nextLv].name}」：好感 ${needAff}${S.player.level < needLv ? `，並需要玩家 Lv${needLv}` : ''}（目前好感 ${affShow(b.aff)}，好感越高提升越慢）`;
    }
    const perks = [1, 2, 3, 4].map((l) => `<li class="${b.lv >= l ? 'got' : ''}"><b>Lv${l} ${BOND_PERKS[m][l].name}</b>：${BOND_PERKS[m][l].perk}${b.lv >= l && STORIES[m + l] ? ` ${btn('replay:' + m + l, '▶ 劇情', false, 'link')}` : ''}</li>`).join('');
    return `<div class="card bond-card" style="--c:${M.hex}">
      <div class="bc-head"><div class="bc-av">${portrait(m, b.lv >= 3 ? 'happy' : 'smile', 'casual')}</div>
      <div><h2>${esc(nameOf(m))} <small>${M.role}</small></h2><p>${M.trait}</p><p class="quote">${M.theme}</p>
      <div class="aff-row">${bar(b.aff, 100, 'aff big')}<b>${affShow(b.aff)}</b><span class="lvtag">${b.lv ? '羈絆 Lv' + b.lv : '未開啟'}</span></div>
      <div class="marks">${[35, 60, 85].map((v) => `<span style="left:${v}%">${v}</span>`).join('')}</div>
      <p class="next">${next}</p></div></div>
      <div class="bc-body"><div><h4>專屬 buff：${M.buff.icon} ${M.buff.name}</h4><p>${M.buff.desc}</p><p class="tiny-note">守護的困境：${M.domain}</p></div>
      <ul class="perks">${perks}</ul>
      <div class="gallery">${['smile', 'concern', 'happy'].map((e) => `<figure>${avatarSVG(m, e, 'casual')}<figcaption>${{ smile: '微笑', concern: '關心', happy: '開心' }[e]}</figcaption></figure>`).join('')}<figure>${avatarSVG(m, 'smile', 'formal')}<figcaption>正式</figcaption></figure></div></div>
    </div>`;
  }).join('');
  const shares = S.shares.length ? `<div class="card"><h3>📱 ${esc(nameOf('sis'))}的分享</h3><ul class="shares">${S.shares.slice(0, 12).map((x) => `<li><span>${D.md(x.d)}</span>${esc(x.t)}</li>`).join('')}</ul></div>` : '';
  const items = `<div class="card"><h3>羈絆道具</h3><div class="item-grid">${Object.entries(ITEMS).map(([k, it]) => `<div class="item"><span class="ic">${it.icon}</span><div><b>${it.name} ×${S.items[k]}</b><p>${it.desc}</p></div></div>`).join('')}</div></div>`;
  return `<div class="stack">${hero}${cards}${items}${shares}</div>`;
}

// ---------------------------------------------------------------------
//  技能
// ---------------------------------------------------------------------
function renderSkills() {
  const locked = S.player.level < 2;
  const P = S.player.skills;
  const cols = Object.entries(BRANCH).map(([br, B]) => {
    const list = SKILLS.filter((s) => s.br === br);
    return `<div class="branch" style="--c:${B.color}"><h3>${B.name}<small>${B.sub}</small></h3>${list.map((s, i) => {
      const prev = list[i - 1];
      const has = !!P[s.id];
      const reqOK = !prev || P[prev.id];
      const can = !locked && !has && reqOK && S.player.sp >= s.cost;
      const why = has ? '已學會' : locked ? '玩家 Lv2 開放' : !reqOK ? `先學「${prev.name}」` : S.player.sp < s.cost ? '技能點不足' : '';
      return `<div class="skill${has ? ' got' : ''}${can ? ' can' : ''}"><div class="sk-h"><b>${s.name}</b><span class="cost">${s.cost} 點</span></div><p>${s.desc}</p>
        ${has ? chip('✓ 已學會', 'ok') : can ? btn('learn:' + s.id, '學習', false, 'primary sm') : `<span class="hint">${why}</span>`}</div>`;
    }).join('<div class="sk-line"></div>')}</div>`;
  }).join('');
  return `<div class="card"><div class="phase-h"><span class="ph-ic">🌳</span><div><h2>技能樹</h2><p class="sub">${locked ? '🔒 玩家 Lv2 時開放。' : ''}可用技能點：<b class="spv">${S.player.sp}</b>　·　每升 1 級、每次完成週自律挑戰，各得 1 點。</p></div></div>
    <div class="branches">${cols}</div></div>`;
}

// ---------------------------------------------------------------------
//  挑戰
// ---------------------------------------------------------------------
function renderQuests() {
  const pdq = playDate();
  const d = pdq && pdq <= semEnd() ? pdq : today();
  const mon = D.monday(d);
  let h = '';
  if (S.player.level < 3) h += `<div class="card"><h3>週常挑戰</h3><p class="muted">🔒 玩家 Lv3 解鎖（目前 Lv${S.player.level}）。</p></div>`;
  else {
    const st = weekStatus(mon);
    const past = Object.entries(S.weekly).filter(([, v]) => v.disc != null || v.grit != null).sort((a, b) => (a[0] < b[0] ? 1 : -1)).slice(0, 4);
    h += `<div class="card"><h3>週常挑戰 · ${D.md(mon)}–${D.md(D.add(mon, 6))}</h3>
      <div class="qc"><b>每週自律挑戰</b>：這週所有早八課都出席（含遲到）。<div class="prog">${bar(st.earlyOk, Math.max(1, st.early), 'disc')}<span>${st.earlyOk}/${st.early}</span></div><small>獎勵：周自律寶箱（技能點 +1、全員好感 +5）</small></div>
      <div class="qc"><b>每週堅毅挑戰</b>：這週沒有中途離開、沒有整天缺席。<div class="prog"><span>中途離開 ${st.left} 次 · 整天缺席 ${st.fullAbsentDays} 天</span></div><small>獎勵：堅毅寶箱（堅毅 +10、${esc(nameOf('dad'))}好感 +8）</small></div>
      ${past.length ? `<p class="tiny-note">近期結果：${past.map(([k, v]) => `${D.md(k)} 週 ${v.disc ? '自律✅' : v.disc === false ? '自律—' : ''} ${v.grit ? '堅毅✅' : v.grit === false ? '堅毅—' : ''}`).join('　')}</p>` : ''}</div>`;
  }
  if (S.player.level < 4) h += `<div class="card"><h3>月度成長挑戰</h3><p class="muted">🔒 玩家 Lv4 解鎖。整個月的無故缺課（含未回報、未補救的缺席）不超過 1 次，就能解鎖家庭月度分享會。</p></div>`;
  else {
    const ms = monthStatus(D.month(d));
    h += `<div class="card"><h3>月度成長挑戰 · ${D.month(d).replace('-', ' 年 ')} 月</h3><p>本月無故缺課：<b>${ms.miss}</b> 次（≤ 1 次達成）。獎勵：家庭月度分享會劇情、全屬性 +10。</p></div>`;
  }
  const weakNames = S.schedule.filter((s) => (S.settings.weakIds || []).includes(s.id)).map((s) => `${s.name}（${D.wname(s.day)}）`);
  h += `<div class="card"><h3>⚔️ 弱項攻克</h3><p>連續 5 次出席你最抗拒的課，就能解鎖${esc(nameOf('sis'))}的專屬崇拜劇情與元氣糖果 ×2。</p>
    <p>目前的弱項：${weakNames.length ? weakNames.map((n) => chip(esc(n), 'warn')).join(' ') : '<span class="muted">尚未設定</span>'} ${btn('tab:settings', '到設定修改', false, 'link')}</p>
    <div class="prog">${bar(S.counters.weakRun, 5, 'grit')}<span>${S.counters.weakRun}/5 · 已攻克 ${S.counters.weakDone} 次</span></div></div>`;
  // 限時活動
  const blocks = holidayBlocks().filter((b) => b.end >= S.settings.semStart);
  const hb = blocks.map((b) => {
    const st = holidayStatus(b);
    const label = { missed: '遊戲開始前', won: '✅ 成功', lost: '未達成', future: '尚未開始', announce: '即將開始', during: '進行中', post: '收假週進行中' }[st.state];
    return `<li><b>${D.md(b.start)}–${D.md(b.end)}</b> ${esc(b.names)} · ${label}${st.state === 'during' || st.state === 'post' ? `（起床 ${st.wakeOk}/${st.total}${st.postFail ? '、收假週有缺課' : ''}）` : ''}</li>`;
  }).join('');
  const ms = midStatus();
  const midLabel = { none: '未設定', missed: '已結束（遊戲開始前）', won: '✅ 完成', lost: '未達成', future: '尚未開始', active: `進行中：成長能量 ${ms.energy}/10` }[ms.state];
  const fw = finWindow();
  h += `<div class="card"><h3>限時活動</h3>
    <div class="qc"><b>🏔️ 連假守護戰</b>：連假前 3 天開啟。連假每天準時起床，收假後第一週全勤 → 全員好感 +10、家族團圓禮包、全家福紀念插圖。<ul class="ev">${hb || '<li class="muted">這學期沒有三天以上的連假</li>'}</ul></div>
    <div class="qc"><b>📖 期中衝刺季</b>（期中考週前 2 週${ms.w ? `：${D.md(ms.w.start)}–${D.md(ms.w.end)}` : ''}）：出勤＋課後複習累積成長能量，複習學識加倍 → 爸爸的考前加油劇情。<p>狀態：${midLabel}</p></div>
    <div class="qc"><b>⚔️ 期末最終決戰</b>（${D.md(fw.start)}–${D.md(fw.end)}）：經驗 +20%、複習學識加倍，學期最後一天結算結局。<p>狀態：${(playDate() || today()) > fw.end ? '已結束' : inWin(fw, playDate() || today()) ? '進行中' : `${D.diff(playDate() || today(), fw.start)} 天後開始`}</p></div></div>`;
  // 徽章與收藏
  h += `<div class="card"><h3>勇者徽章牆</h3><div class="badges">${ACHV.map((a) => `<div class="badge${S.achievements[a.id] ? ' got' : ''}" title="${esc(a.desc)}"><span>${S.achievements[a.id] ? a.icon : '🔒'}</span><b>${a.name}</b><small>${a.desc}</small></div>`).join('')}</div></div>`;
  h += `<div class="card"><h3>羈絆道具收藏</h3><div class="badges">${Object.entries(COLLECTION).map(([k, c]) => S.collection[k]
    ? `<button class="badge got" data-act="collect:${k}"><span>${c.icon}</span><b>${c.name}</b><small>${c.from}</small></button>`
    : `<div class="badge"><span>❔</span><b>？？？</b><small>${c.from}</small></div>`).join('')}</div></div>`;
  return `<div class="stack">${h}</div>`;
}

// ---------------------------------------------------------------------
//  紀念冊
// ---------------------------------------------------------------------
function albumOpen(id) { return !!S.album[id] || !!S.ending; }
function renderAlbum() {
  const n = ALBUM.filter((id) => S.album[id]).length;
  return `<div class="card"><div class="phase-h"><span class="ph-ic">📖</span><div><h2>家族紀念冊</h2><p class="sub">已收集 ${n}/${ALBUM.length} 張。${S.ending ? '學期結束，所有回憶都已開放回顧。' : '解鎖的劇情插圖會依序放進這裡，隨時可以回看。'}</p></div></div>
    <div class="album">${ALBUM.map((id) => albumOpen(id)
    ? `<button class="page" data-act="replay:${id}">${storyScene(id)}<b>${STORIES[id].title}</b><small>${S.album[id] ? D.md(S.album[id]) : '回憶'}</small></button>`
    : `<div class="page locked"><div class="lk">？</div><b>未解鎖</b><small>${ALBUM_HINT[id]}</small></div>`).join('')}</div></div>`;
}

// ---------------------------------------------------------------------
//  紀錄
// ---------------------------------------------------------------------
function dayCellClass(d) {
  if (holName(d)) return 'hol';
  const sm = S.days[d] && S.days[d].summary;
  const ss = sessionsOn(d);
  if (!S.createdAt || d < S.createdAt) return ss.length ? 'pre' : 'off';
  if (sm) {
    const c = sm.items.filter((i) => i.o !== 'cancel');
    if (!c.length) return 'rest';
    if (c.every((i) => i.o === 'none')) return 'none';
    if (sm.perfect) return 'perfect';
    if (sm.full) return 'full';
    const ok = c.filter((i) => i.o === 'perfect' || i.o === 'late' || i.o === 'leave').length;
    return ok / c.length >= 0.5 ? 'partial' : 'bad';
  }
  return ss.length ? 'future' : 'off';
}

function renderRecords() {
  const to = S.settledThrough || S.createdAt;
  const st = attendanceStats(S.createdAt, to && to < semEnd() ? to : semEnd());
  const rate = st.rate == null ? null : st.rate;
  const bt = bondTotal();
  const pred = rate == null ? null : endingType(rate, bt);
  const pname = { perfect: '完美成長', steady: '穩步向前', regret: '留有遺憾' };
  let h = `<div class="card"><h3>出勤總覽（${S.createdAt ? D.md(S.createdAt) : '—'} 起）</h3>
    <div class="big-stats"><div><b>${rate == null ? '—' : Math.round(rate * 100) + '%'}</b><span>出勤達成率</span></div><div><b>${st.counted}</b><span>已結算的課</span></div><div><b>${bt}</b><span>羈絆總值</span></div><div><b>${knowValue()}</b><span>學識值</span></div></div>
    <div class="out-row">${['perfect', 'late', 'left', 'absent', 'leave', 'none', 'cancel'].map((k) => `<span class="st ${OUT[k].cls}">${OUT[k].short} ${st[k] || 0}</span>`).join('')}</div>
    <p class="tiny-note">達成率計算：準時、遲到 = 1，中途離開 = 0.5（用了堅毅勳章算 1），缺席、請假、未回報 = 0；停課不計入。</p></div>`;
  h += `<div class="card"><h3>結局預測</h3><p>${pred ? `照目前的狀況，學期末會是 <b>${pname[pred]}</b> 結局。` : '開始回報出勤後就會出現預測。'}</p>
    <table class="tbl"><tr><th>結局</th><th>條件</th></tr>
    <tr class="${pred === 'perfect' ? 'hl' : ''}"><td>完美成長</td><td>出勤達成率 ≥ 90%，且羈絆總值 ≥ 200</td></tr>
    <tr class="${pred === 'steady' ? 'hl' : ''}"><td>穩步向前</td><td>出勤達成率 ≥ 70%，且羈絆總值 ≥ 120</td></tr>
    <tr class="${pred === 'regret' ? 'hl' : ''}"><td>留有遺憾</td><td>其他情況（家人不會責備，永遠有重來的機會）</td></tr></table></div>`;
  // 日曆
  const start = D.monday(S.settings.semStart);
  let cal = `<div class="cal"><div class="ch"></div>${'一二三四五六日'.split('').map((x) => `<div class="ch">${x}</div>`).join('')}`;
  for (let w = 0; w < S.settings.weeks; w++) {
    cal += `<div class="cw">W${w + 1}</div>`;
    for (let i = 0; i < 7; i++) {
      const d = D.add(start, w * 7 + i);
      const cls = dayCellClass(d);
      cal += `<button class="cd ${cls}${d === today() ? ' now' : ''}" data-act="dayinfo:${d}" title="${D.label(d)}${holName(d) ? ' ' + holName(d) : ''}">${Number(d.slice(8))}</button>`;
    }
  }
  cal += `</div><div class="legend">${[['perfect', '全日完美'], ['full', '全日出席'], ['partial', '部分出席'], ['bad', '缺課偏多'], ['none', '未回報'], ['hol', '國定假日'], ['pre', '遊戲開始前'], ['future', '未來的上課日']].map(([c, n]) => `<span><i class="cd ${c}"></i>${n}</span>`).join('')}</div>`;
  h += `<div class="card"><h3>學期日曆</h3>${cal}</div>`;
  // 各課
  const per = {};
  for (let d = S.createdAt; d && d <= (S.settledThrough || ''); d = D.add(d, 1)) {
    const items = summaryItems(d);
    if (!items) continue;
    items.forEach((i) => {
      if (i.o === 'cancel') return;
      const p = per[i.id] || (per[i.id] = { name: i.name, n: 0, ok: 0 });
      p.n++;
      if (i.o === 'perfect' || i.o === 'late') p.ok++;
    });
  }
  const rows = Object.values(per);
  h += `<div class="card"><h3>各課出席</h3>${rows.length ? `<table class="tbl"><tr><th>課程</th><th>出席</th><th>比例</th></tr>${rows.map((p) => `<tr><td>${esc(p.name)}</td><td>${p.ok}/${p.n}</td><td>${bar(p.ok, p.n, p.ok / p.n >= 0.9 ? 'know' : p.ok / p.n >= 0.7 ? 'mood' : 'grit')}</td></tr>`).join('')}</table>` : '<p class="muted">還沒有結算過的課。</p>'}</div>`;
  h += `<div class="card"><h3>修行日誌</h3><ul class="log">${S.log.slice(0, 40).map((l) => `<li><span>${D.md(l.d)}</span>${esc(l.t)}</li>`).join('') || '<li class="muted">還沒有紀錄</li>'}</ul></div>`;
  return `<div class="stack">${h}</div>`;
}

