function renderSettings() {
  const st = S.settings;
  const who = [['hero', S.profile.hero || '主角'], ['mom', nameOf('mom')], ['dad', nameOf('dad')], ['sis', nameOf('sis')]];
  const photos = who.map(([k, n]) => `<div class="ph-slot">${portrait(k, 'smile', 'casual')}<b>${esc(n)}</b>
    <label class="btn ghost sm">上傳照片<input type="file" accept="image/*" data-photo="${k}" hidden></label>${photoOf(k) || (S.profile.photoRefs && S.profile.photoRefs[k]) ? btn('delphoto:' + k, '移除', false, 'link') : ''}</div>`).join('');
  const days = [1, 2, 3, 4, 5, 6, 7];
  const rows = S.schedule.map((s) => `<tr data-row="${s.id}">
    <td><input data-f="name" value="${esc(s.name)}"></td>
    <td><select data-f="day">${days.map((x) => `<option value="${x}"${Number(s.day) === x ? ' selected' : ''}>${'一二三四五六日'[x - 1]}</option>`).join('')}</select></td>
    <td><input type="time" data-f="start" value="${esc(s.start)}"></td><td><input type="time" data-f="end" value="${esc(s.end)}"></td>
    <td><input data-f="room" value="${esc(s.room || '')}" class="sm-in"></td>
    <td><select data-f="diff">${[1, 2, 3, 4].map((x) => `<option value="${x}"${Number(s.diff) === x ? ' selected' : ''}>${'★'.repeat(x)}</option>`).join('')}</select></td>
    <td><select data-f="guardian">${MEMBERS.map((m) => `<option value="${m}"${s.guardian === m ? ' selected' : ''}>${esc(nameOf(m))}</option>`).join('')}</select></td>
    <td><select data-f="parity">${[['all', '每週'], ['odd', '單週'], ['even', '雙週']].map(([v, n]) => `<option value="${v}"${(s.parity || 'all') === v ? ' selected' : ''}>${n}</option>`).join('')}</select></td>
    <td><input type="date" data-f="from" value="${esc(s.from || '')}"></td><td><input type="date" data-f="to" value="${esc(s.to || '')}"></td>
    <td class="ck"><input type="checkbox" data-f="weak"${(st.weakIds || []).includes(s.id) ? ' checked' : ''}></td>
    <td><button class="link" data-act="delcourse:${s.id}">刪除</button></td></tr>
    ${s.note ? `<tr class="note-row"><td colspan="12">💬 ${esc(s.note)}</td></tr>` : ''}`).join('');
  const srows = (S.sisSchedule || []).map((g) => `<tr data-srow="${g.id}">
    <td><input data-g="icon" value="${esc(g.icon || '')}" class="xs-in" maxlength="4"></td>
    <td><input data-g="name" value="${esc(g.name)}"></td>
    <td><select data-g="day">${days.map((x) => `<option value="${x}"${Number(g.day) === x ? ' selected' : ''}>${'一二三四五六日'[x - 1]}</option>`).join('')}</select></td>
    <td><input type="time" data-g="start" value="${esc(g.start)}"></td><td><input type="time" data-g="end" value="${esc(g.end)}"></td>
    <td><input data-g="room" value="${esc(g.room || '')}" class="sm-in"></td>
    <td><button class="link" data-act="delsis:${g.id}">刪除</button></td></tr>`).join('');
  return `<div class="stack">
  <div class="card"><h3>角色</h3>
    <div class="form grid2">
      <label>主角名字<input data-pf="hero" value="${esc(S.profile.hero)}" maxlength="12"></label>
      <label>媽媽的稱呼<input data-pf="mom" value="${esc(nameOf('mom'))}" maxlength="8"></label>
      <label>爸爸的稱呼<input data-pf="dad" value="${esc(nameOf('dad'))}" maxlength="8"></label>
      <label>妹妹的稱呼<input data-pf="sis" value="${esc(nameOf('sis'))}" maxlength="8"></label>
      <label>妹妹的學校與科系<input data-pf="sisSchool" value="${esc(S.profile.sisSchool || '')}" maxlength="20"></label>
    </div>${btn('saveprofile', '儲存', false, 'primary sm')}
    <h4>頭像風格</h4>
    <div class="radio-row"><label><input type="radio" name="avs" data-bind="avatarStyle" value="toon"${useToon() ? ' checked' : ''}> 全家福卡通頭像（預設）</label>
      <label><input type="radio" name="avs" data-bind="avatarStyle" value="svg"${useToon() ? '' : ' checked'}> 手繪角色</label></div>
    <p class="hint">「全家福卡通頭像」是用你提供的全家福照片去背、卡通化做成的，已內建在這個檔案裡（不會上傳到任何地方）。劇情插圖一律用手繪角色，造型也依照全家福調整過。分享這個 HTML 檔給別人時，對方也會看到這些頭像。</p>
    <h4>自訂照片（選用）</h4><p class="hint">也可以替某位家人上傳新的大頭照，會優先取代卡通頭像。照片只存在這個瀏覽器。</p>
    <div class="ph-grid">${photos}</div>
    <label class="ck-l"><input type="checkbox" data-bind="usePhotos"${S.profile.usePhotos ? ' checked' : ''}> 使用上傳的照片當頭像</label>
    <label class="ck-l"><input type="checkbox" data-bind="voice"${S.profile.voice ? ' checked' : ''}> 晨間叮嚀語音（媽媽羈絆 Lv2 後，準時起床時用瀏覽器語音唸出來）</label></div>

  <div class="card"><h3>學期與作息</h3><div class="form grid3">
    <label>學期開始日（第 1 週週一）<input type="date" data-sf="semStart" value="${esc(st.semStart)}"></label>
    <label>學期週數<input type="number" min="4" max="24" data-sf="weeks" value="${st.weeks}"></label>
    <label>期中考週（第幾週）<input type="number" min="0" max="24" data-sf="midWeek" value="${st.midWeek}"></label>
    <label>就寢目標<input type="time" data-sf="bedtime" value="${esc(st.bedtime)}"></label>
    <label>平日起床目標<input type="time" data-sf="wake" value="${esc(st.wake)}"></label></div>
    <p class="hint">學期：${D.md(st.semStart)} – ${D.md(semEnd())}（${st.weeks} 週）。期末最終決戰是最後 2 週。</p>${btn('savesem', '儲存學期設定', false, 'primary sm')}</div>

  <div class="card"><h3>課表（副本）</h3>
    <p class="hint">難度參考：★ 下午、輕鬆課 ／ ★★ 上午非早八、普通必修 ／ ★★★ 早八、3 小時連堂、專業核心 ／ ★★★★ 孤立的單節課。熬夜後與收假後一週的早課，會自動升級為 ★★★★。「弱項」打勾的課會計入弱項攻克挑戰。</p>
    <div class="tbl-wrap"><table class="tbl sched"><tr><th>課名</th><th>星期</th><th>開始</th><th>結束</th><th>教室</th><th>難度</th><th>守護</th><th>週次</th><th>開始日</th><th>結束日</th><th>弱項</th><th></th></tr>${rows}</table></div>
    <div class="row">${btn('addcourse', '＋ 新增一堂課', false, 'ghost sm')}${btn('savesched', '儲存課表', false, 'primary sm')}${btn('resetsched', '還原預設課表', false, 'link')}${btn('clearsched', '清空課表', false, 'link')}</div></div>

  <div class="card"><h3>${esc(nameOf('sis'))}的課表（${esc(S.profile.sisSchool || '')}）</h3>
    <p class="hint">用在「兄妹」分頁、今日側欄與兄妹同步早八。只要記錄星期與時間，不需要回報出勤。國定假日沿用下面的設定。</p>
    <div class="tbl-wrap"><table class="tbl sched"><tr><th>圖示</th><th>課名</th><th>星期</th><th>開始</th><th>結束</th><th>教室</th><th></th></tr>${srows}</table></div>
    <div class="row">${btn('addsis', '＋ 新增一堂課', false, 'ghost sm')}${btn('savesis', '儲存妹妹的課表', false, 'primary sm')}${btn('resetsis', '還原預設', false, 'link')}</div></div>

  <div class="card"><h3>國定假日與停課日</h3><ul class="hol">${st.holidays.slice().sort((a, b) => (a.date < b.date ? -1 : 1)).map((h) => `<li>${D.label(h.date)} ${esc(h.name)} ${btn('delhol:' + h.date, '刪除', false, 'link')}</li>`).join('')}</ul>
    <div class="row"><input type="date" id="hol-d"><input id="hol-n" placeholder="名稱，例如：校慶補假" maxlength="12">${btn('addhol', '新增', false, 'ghost sm')}</div></div>

  ${HOOKS.settingsCard ? HOOKS.settingsCard() : ''}<div class="card"><h3>存檔</h3><p class="hint">${HOOKS.saveNote ? HOOKS.saveNote() : '進度存在這個瀏覽器（localStorage）。換電腦、換瀏覽器或清除瀏覽資料前，請先匯出備份。'}</p>
    ${S.tasks && S.tasks.pe && S.tasks.pe.hidden && !S.tasks.pe.done ? `<p class="hint">體育期中退選提醒已隱藏。${btn('petaskshow', '恢復提醒', false, 'link')}</p>` : ''}
    <div class="row">${btn('export', '⬇️ 匯出存檔', false, 'ghost')}<label class="btn ghost">⬆️ 匯入存檔<input type="file" accept=".json,application/json" data-import="1" hidden></label>${btn('reset', '重新開始遊戲', false, 'danger')}</div></div>
  <div class="card"><h3>關於</h3><p>《晨光羈絆：學園修行物語》v1.1 · 依照企劃書製作的單檔文字養成 RPG。v1.1：全家福卡通頭像、兄妹分頁與同步早八、移除體育課。${btn('help', '遊戲說明', false, 'link')}</p></div>
  </div>`;
}

// ---------------------------------------------------------------------
//  對話框與佇列
// ---------------------------------------------------------------------
function openModal(html, cls = '') {
  const m = $('#modal');
  m.innerHTML = `<div class="modal-card ${cls}" role="dialog" aria-modal="true">${html}</div>`;
  m.hidden = false;
  modalOpen = true;
  const b = m.querySelector('.btn.primary, button');
  if (b) setTimeout(() => b.focus(), 30);
}
function closeModal() {
  const m = $('#modal');
  m.hidden = true;
  m.innerHTML = '';
  modalOpen = false;
  UI.story = null; UI.event = null;
  render();
  setTimeout(flushQueue, 60);
}
function flushQueue() {
  if (modalOpen) return;
  const q = S.queue.shift();
  save();
  if (!q) { showToasts(); return; }
  if (q.type === 'story') return playStory(q.id);
  if (q.type === 'levelup') return showLevelUp(q.lv);
  if (q.type === 'summary') return showSummary(q.sum);
  if (q.type === 'msg') return openModal(`<h2>${q.title}</h2>${q.html}<div class="actions">${btn('close', '好', false, 'primary')}</div>`);
  if (q.type === 'help') return showHelp();
  if (q.type === 'event') return showEvent(pickEvent(q.d), q.d, 'random');
  flushQueue();
}

function speakerHTML(sp) {
  if (sp === 'n') return '';
  if (sp === 'sys') return `<div class="sp sys">✦ 系統</div>`;
  return `<div class="sp">${portrait(sp, 'smile', 'casual', 'mini')}<b style="color:${sp === 'hero' ? '#3f8f76' : MEMBER[sp].hex}">${esc(nameOf(sp))}</b></div>`;
}

function playStory(id) {
  const st = STORIES[id];
  if (!st) return flushQueue();
  let lines = st.lines;
  if (st.variants) lines = pick(st.variants).concat(st.tail || []);
  UI.story = { id, lines, i: 0 };
  drawStory();
}
function drawStory() {
  const { id, lines, i } = UI.story;
  const st = STORIES[id];
  const [sp, text] = lines[i];
  const last = i >= lines.length - 1;
  openModal(`<div class="story"><div class="story-scene">${storyScene(id)}<div class="story-title">${st.title}</div></div>
    <div class="dlg ${sp === 'n' ? 'narr' : sp === 'sys' ? 'sys' : ''}">${speakerHTML(sp)}<p>${esc(fill(text))}</p></div>
    <div class="actions"><span class="hint">${i + 1}/${lines.length}</span>${!last ? btn('skipstory', '跳過', false, 'link') : ''}${btn('storynext', last ? (S.album[id] ? '收進紀念冊 ✓' : '關閉') : '繼續 ▶', false, 'primary')}</div></div>`, 'wide');
}

function showLevelUp(lv) {
  const L = LEVELS[lv];
  const extra = { 2: `${nameOf('dad')}的羈絆線開啟了！技能樹也開放了，到「技能」看看吧。`, 3: `${nameOf('sis')}的羈絆線開啟了！週常挑戰也開始了。`, 4: '全員羈絆可以提升到 Lv2，月度挑戰開放。', 5: '全員羈絆可以提升到 Lv3 以上，終極劇情解鎖。' }[lv] || '';
  openModal(`<div class="lvup"><div class="burst">Lv${lv}</div><h2>升級！「${L.title}」</h2><p>解鎖：${L.unlock}</p><p>${esc(extra)}</p><p class="gain">技能點 +1（目前 ${S.player.sp} 點）</p>
    <div class="actions">${btn('close', '太好了', false, 'primary')}</div></div>`);
}

function showSummary(sum) {
  const lines = [];
  sum.levelUps.forEach((l) => lines.push(`⬆️ 升級到 Lv${l}「${LEVELS[l].title}」`));
  sum.bondUps.forEach((b) => lines.push(`💞 ${nameOf(b.m)}羈絆 Lv${b.lv}「${BOND_PERKS[b.m][b.lv].name}」`));
  const sm = S.days[sum.date] && S.days[sum.date].summary;
  openModal(`<h2>✨ 休整總結 · ${D.label(sum.date)}</h2>
    ${sm ? summaryInner(sm) : ''}
    ${sum.notes.length ? `<ul class="notes">${sum.notes.map((n) => `<li>${esc(n)}</li>`).join('')}</ul>` : ''}
    ${(sum.lines.length || lines.length) ? `<ul class="notes big">${lines.concat(sum.lines).map((n) => `<li>${esc(n)}</li>`).join('')}</ul>` : ''}
    <div class="actions">${btn('close', '好', false, 'primary')}</div>`);
}
function summaryInner(sm) {
  const att = sm.items.filter((i) => i.o !== 'cancel');
  const ok = att.filter((i) => i.o === 'perfect' || i.o === 'late').length;
  return `<p>${att.length ? `出席 ${ok}/${att.length} 堂${sm.perfect ? ' · ☀️ 全日完美通關' : sm.full ? ' · 全日出席' : ''}` : '休息日'}</p>
    <div class="p-g sum-g"><div><b>+${sm.exp}</b><span>經驗</span></div><div><b>+${sm.know}</b><span>學識點</span></div><div><b>${signed(sm.disc)}</b><span>自律</span></div><div><b>${signed(sm.grit)}</b><span>堅毅</span></div>
    ${MEMBERS.map((m) => `<div><b>${signed(sm.aff[m] || 0)}</b><span>${esc(nameOf(m))}</span></div>`).join('')}</div>`;
}

function showEvent(ev, d, ctx) {
  UI.event = { ev, d, ctx, chosen: null };
  drawEvent();
}
function drawEvent() {
  const { ev, chosen, fxText } = UI.event;
  if (chosen == null) {
    openModal(`<div class="event"><div class="ev-tag">🎲 修行試煉</div><h2>${esc(fill(ev.title))}</h2><p>${esc(fill(ev.text))}</p>
      <div class="opts">${ev.opts.map((o, i) => btn('evpick:' + i, `${'ABC'[i]}　${esc(fill(o.t))}`, false, 'opt')).join('')}</div>
      <p class="tiny-note">試煉是情境選擇，只影響屬性與好感，不會改動你的出勤紀錄。</p></div>`);
  } else {
    const o = ev.opts[chosen];
    openModal(`<div class="event"><div class="ev-tag">🎲 修行試煉</div><h2>${esc(fill(ev.title))}</h2><p class="chosen">你選擇了：${esc(fill(o.t))}</p><p>${esc(fill(o.r))}</p>
      ${fxText.length ? `<div class="fx">${fxText.map((t) => chip(esc(t), /−/.test(t) ? 'neg' : 'aff')).join('')}</div>` : ''}
      <div class="actions">${btn('close', '好', false, 'primary')}</div></div>`);
  }
}

function showCare(m, kind) {
  const line = kind === 'left' ? LINES.left[m] : pick(LINES.care[m]);
  const sub = kind === 'left' ? '（副本敗退：獎勵 30%）' : `（${nameOf(m)}有點擔心 · 好感 −1）`;
  const rl = remedyLeft(playDate());
  openModal(`<div class="care">${portrait(m, 'concern', 'casual', 'big')}<div><b>${esc(nameOf(m))}</b><p>${esc(fill(line))}</p><p class="tiny-note">${sub}</p>
    ${kind !== 'left' && rl > 0 ? `<p class="tiny-note">💡 本週還可以用 ${rl} 次補救任務，完成後能恢復這堂課一半的獎勵與好感。</p>` : ''}</div></div>
    <div class="actions">${btn('close', '好，我知道了', false, 'primary')}</div>`);
}

function showHelp() {
  openModal(`<h2>遊戲說明</h2><div class="help">
  <h4>每天的流程（約 5 分鐘）</h4><ol><li><b>晨起啟動</b>：回報昨晚有沒有準時睡、今天起床狀況，選擇要啟用的家人 buff。</li><li><b>副本挑戰</b>：每堂課是一個副本，依真實出勤回報結果。</li><li><b>晚間羈絆</b>：跟一位家人互動、勾選課後複習、設定今晚的就寢時間。</li><li><b>休整總結</b>：領取當天獎勵、升級、解鎖劇情。</li></ol>
  <h4>通關狀態</h4><table class="tbl"><tr><td>準時</td><td>完美通關，100% 獎勵</td></tr><tr><td>遲到</td><td>艱難通關，70% 獎勵（遲到也好過缺席）</td></tr><tr><td>中途離開</td><td>副本敗退，30% 獎勵，堅毅 −3</td></tr><tr><td>缺席</td><td>副本失敗，沒有獎勵，守護家人好感 −1，會收到關心</td></tr><tr><td>請假／停課</td><td>請假不扣好感但算未出席；停課不計入</td></tr></table>
  <h4>副本難度</h4><table class="tbl">${[1, 2, 3, 4].map((x) => `<tr><td>${'★'.repeat(x)} ${DIFF[x].name}</td><td>${DIFF[x].scene}</td><td>經驗 ${DIFF[x].exp}・學識 ${DIFF[x].know}・好感 ${DIFF[x].aff}</td></tr>`).join('')}</table>
  <h4>加成</h4><ul><li>全日完美通關：當天經驗與好感 ×1.5。</li><li>連續全勤 3 天：經驗 +20%；7 天：+50%。</li><li>新手期（開學前 3 週）+30%；期末最終決戰 +20%；好心情 +10%；技能另有加成。</li></ul>
  <h4>成長</h4><ul><li>四大屬性：自律、堅毅、學識（0–100），以及三位家人各自的好感（0–100）。學識會隨整個學期的上課與複習慢慢累積。</li><li>等級 Lv1–Lv5：Lv2 開放爸爸羈絆線與技能樹、Lv3 開放妹妹羈絆線與週常挑戰、Lv4 全員羈絆 Lv2 與月度挑戰、Lv5 全員羈絆 Lv3 與終極劇情。</li><li>羈絆等級：好感 35 → Lv2、60 → Lv3、85 → Lv4（同時要達到對應的玩家等級）。</li><li>好感與自律、堅毅越高，提升就越慢；越接近 100，每次增加的幅度越小。</li></ul>
  <h4>容錯機制</h4><ul><li>單日失敗不連鎖：缺課只影響當天。</li><li>低谷自動關懷：連續 3 個上課日狀態不佳，家人會來關心你，並清除負面狀態。</li><li>補救任務：每週 2 次，缺課後抄筆記、確認進度或自我反省，可恢復 50% 獎勵與好感。</li><li>隨時重啟：任何時候都能「從下一堂課重新出發」。</li></ul>
  <h4>結局</h4><ul><li>完美成長：出勤達成率 ≥ 90% 且羈絆總值 ≥ 200。</li><li>穩步向前：出勤達成率 ≥ 70% 且羈絆總值 ≥ 120。</li><li>留有遺憾：其他情況——家人不會責備，下學期重新來過。</li></ul>
  <h4>兄妹分頁</h4><ul><li>可以看到妹妹（靜宜大學食品營養學系一年級）的課表、今天的行程與即時動態，以及你們兩人的雙人週課表。</li><li>⚡ 兄妹同步早八：週三、週四你們都是早八。你準時（或遲到但有到）出席早八，就能拿到經驗 +10 與妹妹好感；累積 10 次解鎖徽章與專屬劇情。</li><li>每週日結算時，會收到一份兄妹週報。</li></ul>
  <h4>存檔</h4><p>進度存在這個瀏覽器裡。忘了回報的日子可以隔天補登。換裝置前請到「設定」匯出存檔。</p></div>
  <div class="actions">${btn('close', '開始修行', false, 'primary')}</div>`, 'wide');
}

function showDayInfo(d) {
  const sm = S.days[d] && S.days[d].summary;
  const ss = sessionsOn(d);
  let body = '';
  if (sm) body = summaryInner(sm) + `<div class="sum-items">${sm.items.map((i) => `<span class="st ${OUT[i.o].cls}">${esc(i.name)}：${OUT[i.o].short}${i.remedied ? '（已補救）' : ''}</span>`).join('')}</div>`;
  else if (ss.length) body = `<p class="muted">${d > today() ? '還沒到這一天。' : d < (S.createdAt || '') ? '這天在遊戲開始之前。' : '這天還沒結算。'}</p>${ss.map((s) => miniQuest(s, d, null)).join('')}`;
  else body = `<p class="muted">${holName(d) ? '🎌 ' + holName(d) : '沒有課'}</p>`;
  openModal(`<h2>${D.label(d)}${inSem(d) ? ` · 第 ${semWeek(d)} 週` : ''}</h2>${body}<div class="actions">${btn('close', '關閉', false, 'primary')}</div>`);
}

// ---------------------------------------------------------------------
//  操作處理
// ---------------------------------------------------------------------
function curDay() { const d = playDate(); return { d, day: getDay(d) }; }

function report(sid, o) {
  const { d, day } = curDay();
  const s = S.schedule.find((x) => x.id === sid);
  if (!s) return;
  day.reports[sid] = { o, remedied: false, medal: false };
  save();
  render();
  const R = computeDay(d, day);
  const it = R.list.find((x) => x.s.id === sid);
  if (o === 'perfect' || o === 'late') {
    if (o === 'late') toast('⏱️ 遲到也好過缺席！');
    else toast(`⚔️ 完美通關！經驗 +${it ? it.exp : 0}（待領取）`);
    if (early8(s) && sisEarly(d)) toast(`⚡ ${nameOf('sis')}：「${pick(o === 'late' ? ['哥你遲到了吧！不過有到就好～', '這次我贏了！但你有來就算同步！'] : ['報到！我也到教室了！', '平手！我們都準時！', '同步成功～今天也一起加油！'])}」（兄妹同步早八：經驗 +10，待領取）`);
    if (!day.eventDone && Math.random() < 0.35) {
      day.eventDone = true;
      save();
      setTimeout(() => { if (!modalOpen) showEvent(pickEvent(d), d, 'random'); else { S.queue.push({ type: 'event', d }); save(); } }, 450);
    }
  } else if (o === 'absent') {
    if (!day.careShown[sid]) { day.careShown[sid] = true; save(); showCare(S.bonds[s.guardian].lv >= 1 ? s.guardian : 'mom', 'absent'); }
  } else if (o === 'left') {
    showCare(S.bonds[s.guardian].lv >= 1 ? s.guardian : 'mom', 'left');
  } else if (o === 'cancel') toast('停課不計入出勤。');
}

function handle(act, a, el) {
  const pd = playDate();
  switch (act) {
    case 'tab': TAB = a[0]; UI.interWho = null; render(); window.scrollTo({ top: 0, behavior: 'smooth' }); return;
    case 'help': showHelp(); return;
    case 'close': closeModal(); return;
    case 'start': {
      const name = ($('#w-name').value || '').trim() || '振嘉';
      const start = (document.querySelector('input[name="w-start"]:checked') || {}).value || today();
      S.profile.hero = name;
      S.started = true;
      S.createdAt = start;
      S.settledThrough = D.add(start, -1);
      queueStory('prologue');
      queueStory('sisPlan');
      unlockCollect('plan');
      progressUpdate({ lines: [], levelUps: [], bondUps: [] });
      S.queue.push({ type: 'help' });
      logEv('踏上修行之路', start);
      save('start'); render(); flushQueue();
      emit('start');
      return;
    }
    case 'sleep': {
      const { d, day } = curDay();
      const was = day.sleep;
      day.sleep = a[0];
      if (a[0] === 'late' && !day.sleepEvent) { day.sleepEvent = true; save(); render(); showEvent(EVENT_SLEEP, d, 'sleep'); return; }
      if (a[0] === 'ok' && was === 'late') toast('已改為準時睡。');
      save(); render(); return;
    }
    case 'wake': {
      const { day } = curDay();
      const prev = day.wake;
      day.wake = a[0];
      if (a[0] === 'ok' && day.supply) { day.supply = false; S.items.supply++; }
      if (a[0] === 'ok' && prev !== 'ok') {
        if (S.bonds.mom.lv >= 2) { const line = pick(LINES.morningCall); toast(`🔔 ${nameOf('mom')}：「${line}」`); speakLine(line); }
        else toast('⏰ 準時起床！自律 +2（待領取）');
      }
      if ((a[0] === 'snooze' || a[0] === 'over') && day.buffs.includes('mom') && S.bonds.mom.lv >= 1) toast(`🍱 ${nameOf('mom')}：「沒關係，慢慢來，先吃點東西。」`);
      save(); render(); return;
    }
    case 'supply': { const { day } = curDay(); if (S.items.supply > 0 && !day.supply) { S.items.supply--; day.supply = true; toast('🧺 使用居家補給包：這次賴床不扣自律。'); } save(); render(); return; }
    case 'buff': {
      const { day } = curDay();
      const m = a[0];
      if (day.buffs.includes(m)) day.buffs = day.buffs.filter((x) => x !== m);
      else { day.buffs.push(m); while (day.buffs.length > maxBuffs()) day.buffs.shift(); }
      save(); render(); return;
    }
    case 'begin': {
      const { d, day } = curDay();
      if (!day.sleep || !day.wake) return;
      const isClass = sessionsOn(d).length > 0;
      day.phase = isClass ? 'day' : 'evening';
      save(); render();
      const b = postBlock(d);
      if (isClass && b && firstClassAfter(b) === d && !day.postholShown) { day.postholShown = true; save(); showEvent(EVENT_POSTHOL, d, 'posthol'); }
      return;
    }
    case 'rep': report(a[0], a[1]); return;
    case 'unrep': {
      const { day } = curDay();
      const r = day.reports[a[0]];
      if (r && r.medal) S.items.medal++;
      delete day.reports[a[0]];
      save(); render(); return;
    }
    case 'remedy': {
      const sid = a[0];
      openModal(`<h2>🧵 補救任務</h2><p>選一項你真的完成的補救行動。完成後，這堂課可以恢復 50% 的獎勵與好感（本週剩 ${remedyLeft(pd)} 次）。</p>
        <div class="opts">${REMEDY_TASKS.map((t) => btn(`remdo:${sid}:${t.id}`, `<b>${t.name}</b><small>${t.desc}</small>`, false, 'opt')).join('')}</div>
        <div class="actions">${btn('close', '之後再說', false, 'link')}</div>`);
      return;
    }
    case 'remdo': {
      const { day } = curDay();
      const r = day.reports[a[0]];
      if (r && r.o === 'absent' && !r.remedied && remedyLeft(pd) > 0) {
        r.remedied = true; r.task = a[1];
        S.counters.remedies++;
        checkAchievements();
        toast('🧵 補救完成！恢復這堂課 50% 的獎勵與好感（待領取）');
      }
      save(); closeModal(); return;
    }
    case 'medal': {
      const { day } = curDay();
      const r = day.reports[a[0]];
      if (r && r.o === 'left' && !r.medal && S.items.medal > 0) { S.items.medal--; r.medal = true; toast('🎖️ 堅毅勳章：這次中途離開不扣堅毅，也不中斷連續全勤。'); }
      save(); render(); return;
    }
    case 'candy': { const { day } = curDay(); if (S.items.candy > 0 && !day.candy) { S.items.candy--; day.candy = true; toast(`🍬 ${nameOf('sis')}的元氣糖果：疲勞清零、心情 +10！`); } save(); render(); return; }
    case 'restart': {
      const { day } = curDay();
      day.restart = true;
      S.streak.bad = 0; S.streak.prevAbsent = false; S.streak.prevWakeBad = false;
      save(); render();
      const open = MEMBERS.filter((m) => S.bonds[m].lv >= 1);
      openModal(`<h2>↺ 從下一堂課重新出發</h2><div class="restart">${open.map((m) => `<div class="care">${portrait(m, 'happy', 'casual', 'mini')}<div><b>${esc(nameOf(m))}</b><p>${esc(fill(LINES.restart[m]))}</p></div></div>`).join('')}</div>
        <p class="tiny-note">負面狀態已清除：心情回到 60 以上，連續缺課與低潮計數歸零。已經回報的紀錄不會改變。</p><div class="actions">${btn('close', '出發', false, 'primary')}</div>`);
      return;
    }
    case 'toEvening': { const { day } = curDay(); day.phase = 'evening'; UI.interWho = null; save(); render(); window.scrollTo({ top: 0, behavior: 'smooth' }); return; }
    case 'toDay': { const { day } = curDay(); day.phase = 'day'; save(); render(); return; }
    case 'toMorning': { const { day } = curDay(); day.phase = 'morning'; save(); render(); return; }
    case 'iwho': UI.interWho = a[0]; render(); return;
    case 'inter': {
      const { d, day } = curDay();
      const [m, type] = a;
      if (day.inter || S.bonds[m].lv < 1) return;
      const R = computeDay(d, day);
      const special = R.perfectAll;
      const line = special ? pick(LINES.inter[m].special)
        : (m === 'sis' && type === 'share' && sisSessionsOn(d).length && Math.random() < 0.75) ? sisShareLine(d) : pick(LINES.inter[m][type]);
      day.inter = { who: m, type, special, line };
      save(); render();
      openModal(`<div class="care">${portrait(m, 'happy', 'casual', 'big')}<div><b>${esc(nameOf(m))} · ${LINES.interType[type]}${special ? ' · ✨ 特別互動' : ''}</b><p>${esc(fill(line))}</p><p class="tiny-note">${esc(nameOf(m))}好感 +${effAff(m, special ? 3 : 1)}（待領取）</p></div></div><div class="actions">${btn('close', '晚安', false, 'primary')}</div>`);
      return;
    }
    case 'review': { const { day } = curDay(); day.review = !day.review; save(); render(); return; }
    case 'settle': {
      const { d } = curDay();
      const sum = settleDay(d);
      S.queue.unshift({ type: 'summary', sum });
      UI.interWho = null;
      save('settle'); render(); flushQueue();
      emit('settle', { date: d });
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    case 'skip': {
      const t = today();
      if (a[0] === 'one') {
        openModal(`<h2>標記未回報並結算？</h2><p>${D.label(pd)} 的課會全部記為「未回報」（以缺席計算），作息也記為未回報。之後就不能再修改這天了。</p><div class="actions">${btn('close', '取消', false, 'ghost')}${btn('skipok:one', '確定結算', false, 'primary')}</div>`);
      } else {
        openModal(`<h2>一次結算 ${D.diff(pd, t)} 天？</h2><p>從 ${D.label(pd)} 到昨天，還沒回報的課都會記為「未回報」（以缺席計算）。之後就不能再修改了。</p><div class="actions">${btn('close', '取消', false, 'ghost')}${btn('skipok:all', '確定結算', false, 'primary')}</div>`);
      }
      return;
    }
    case 'skipok': {
      const t = today();
      const sums = [];
      if (a[0] === 'one') sums.push(skipDay(playDate()));
      else { while (playDate() < t && playDate() <= semEnd()) sums.push(skipDay(playDate())); }
      const lines = sums.flatMap((s) => s.lines);
      if (lines.length) S.queue.unshift({ type: 'msg', title: '補登結算完成', html: `<ul class="notes">${lines.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>` });
      save(); closeModal(); return;
    }
    case 'replay': UI.story = null; playStory(a[0]); return;
    case 'storynext': {
      if (!UI.story) return closeModal();
      if (UI.story.i < UI.story.lines.length - 1) { UI.story.i++; drawStory(); } else closeModal();
      return;
    }
    case 'skipstory': closeModal(); return;
    case 'evpick': {
      const ev = UI.event;
      if (!ev || ev.chosen != null) return;
      const i = Number(a[0]);
      const o = ev.ev.opts[i];
      ev.chosen = i;
      ev.fxText = applyFx(o.fx, ev.d);
      const day = getDay(ev.d);
      day.events.push({ id: ev.ev.id, c: i });
      if (o.wake) day.wake = o.wake;
      if (ev.ctx === 'random' || ev.ctx === 'posthol') S.counters.events++;
      progressUpdate({ lines: [], levelUps: [], bondUps: [] });
      save();
      drawEvent();
      return;
    }
    case 'learn': {
      const sk = SKILLS.find((s) => s.id === a[0]);
      if (!sk || S.player.skills[sk.id] || S.player.sp < sk.cost || S.player.level < 2) return;
      S.player.sp -= sk.cost;
      S.player.skills[sk.id] = true;
      logEv(`學會技能「${sk.name}」`);
      const sum = progressUpdate({ lines: [], levelUps: [], bondUps: [] });
      toast(`🌳 學會「${sk.name}」！`);
      if (sum.lines.length) S.queue.push({ type: 'msg', title: '技能發動', html: `<ul class="notes">${sum.lines.map((x) => `<li>${esc(x)}</li>`).join('')}</ul>` });
      save(); render(); flushQueue();
      return;
    }
    case 'collect': {
      const c = COLLECTION[a[0]];
      openModal(`<div class="collect"><div class="ic">${c.icon}</div><h2>${c.name}</h2><p>${esc(c.text)}</p><p class="tiny-note">來源：${c.from}・獲得於 ${D.md(S.collection[a[0]])}</p></div><div class="actions">${btn('close', '收好', false, 'primary')}</div>`);
      return;
    }
    case 'dayinfo': showDayInfo(a[0]); return;
    case 'saveprofile': {
      document.querySelectorAll('[data-pf]').forEach((inp) => {
        const k = inp.dataset.pf, v = inp.value.trim();
        if (!v) return;
        if (k === 'hero') S.profile.hero = v; else if (k === 'sisSchool') S.profile.sisSchool = v; else S.profile.names[k] = v;
      });
      save(); render(); toast('已儲存'); return;
    }
    case 'delphoto': delete S.profile.photos[a[0]]; if (S.profile.photoRefs) delete S.profile.photoRefs[a[0]]; save('photo'); render(); emit('photo-delete', { who: a[0] }); return;
    case 'sibday': {
      const base = UI.sibDate || today();
      const n = Number(a[0]);
      UI.sibDate = n === 0 ? null : D.add(base, n);
      if (UI.sibDate === today()) UI.sibDate = null;
      render(); return;
    }
    case 'petask': {
      if (a[0] === 'done' && !S.tasks.pe.done) {
        S.tasks.pe.done = today();
        S.player.exp += 20;
        logEv('完成現實任務：體育期中退選');
        progressUpdate({ lines: [], levelUps: [], bondUps: [] });
        toast('📝 現實任務完成！經驗 +20。停損也是一種負責任的選擇。');
        save(); render(); flushQueue(); return;
      }
      if (a[0] === 'hide') { S.tasks.pe.hidden = true; toast('已隱藏。之後可在「設定 → 存檔」旁找回提醒。'); }
      save(); render(); return;
    }
    case 'petaskshow': S.tasks.pe.hidden = false; save(); render(); toast('已恢復體育退選提醒'); return;
    case 'addsis': {
      collectSisSchedule();
      S.sisSchedule.push({ id: 'g' + Date.now().toString(36), name: '新的課', day: 1, start: '10:10', end: '12:00', room: '', icon: '📚', type: 'gen', note: '' });
      save(); render(); return;
    }
    case 'delsis': collectSisSchedule(); S.sisSchedule = S.sisSchedule.filter((g) => g.id !== a[0]); save(); render(); return;
    case 'savesis': { const ok = collectSisSchedule(); save(); render(); toast(ok ? `已儲存${nameOf('sis')}的課表` : '有幾堂課的時間不正確，已略過修正'); return; }
    case 'resetsis':
      openModal(`<h2>還原${esc(nameOf('sis'))}的預設課表？</h2><p>會換回靜宜大學食品營養學系 115-1 的課表。</p><div class="actions">${btn('close', '取消', false, 'ghost')}${btn('resetsisok', '還原', false, 'primary')}</div>`);
      return;
    case 'resetsisok': S.sisSchedule = SIS_SCHEDULE.map((x) => ({ ...x })); save(); closeModal(); toast('已還原妹妹的課表'); return;
    case 'savesem': {
      const v = {};
      document.querySelectorAll('[data-sf]').forEach((inp) => { v[inp.dataset.sf] = inp.value; });
      if (!isDate(v.semStart)) return toast('學期開始日格式不正確');
      S.settings.semStart = v.semStart;
      S.settings.weeks = clamp(parseInt(v.weeks, 10) || 18, 4, 24);
      S.settings.midWeek = clamp(parseInt(v.midWeek, 10) || 0, 0, 24);
      if (v.bedtime) S.settings.bedtime = v.bedtime;
      if (v.wake) S.settings.wake = v.wake;
      save(); render(); toast('已儲存學期設定'); return;
    }
    case 'addcourse': {
      collectSchedule();
      S.schedule.push({ id: 'c' + Date.now().toString(36), name: '新的課', day: 1, start: '10:10', end: '12:00', room: '', diff: 2, guardian: 'mom', parity: 'all', from: '', to: '', note: '' });
      save(); render(); return;
    }
    case 'delcourse': collectSchedule(); S.schedule = S.schedule.filter((s) => s.id !== a[0]); S.settings.weakIds = (S.settings.weakIds || []).filter((x) => x !== a[0]); save(); render(); return;
    case 'savesched': { const ok = collectSchedule(); save(); render(); toast(ok ? '已儲存課表' : '有幾堂課的時間不正確，已略過修正'); return; }
    case 'resetsched':
      openModal(`<h2>還原預設課表？</h2><p>會換回預先載入的 115-1 化材 1B 課表，你自己新增或修改的課會被覆蓋。已經結算的紀錄不受影響。</p><div class="actions">${btn('close', '取消', false, 'ghost')}${btn('resetschedok', '還原', false, 'primary')}</div>`);
      return;
    case 'resetschedok': S.schedule = DEFAULT_SCHEDULE.map((x) => ({ ...x })); S.settings.weakIds = DEFAULT_WEAK.slice(); save(); closeModal(); toast('已還原預設課表'); return;
    case 'clearsched':
      openModal(`<h2>清空課表？</h2><p>清空後可以從零開始輸入你自己的課。已經結算的紀錄不受影響。</p><div class="actions">${btn('close', '取消', false, 'ghost')}${btn('clearschedok', '清空', false, 'danger')}</div>`);
      return;
    case 'clearschedok': S.schedule = []; S.settings.weakIds = []; save(); closeModal(); return;
    case 'addhol': {
      const d = $('#hol-d').value, n = ($('#hol-n').value || '').trim() || '停課日';
      if (!isDate(d)) return toast('請先選日期');
      if (!S.settings.holidays.some((h) => h.date === d)) S.settings.holidays.push({ date: d, name: n });
      save(); render(); return;
    }
    case 'delhol': S.settings.holidays = S.settings.holidays.filter((h) => h.date !== a[0]); save(); render(); return;
    case 'export': exportSave(); return;
    case 'reset':
      openModal(`<h2>重新開始遊戲？</h2><p>所有進度（等級、羈絆、紀念冊、出勤紀錄）都會清除，而且無法復原。建議先匯出存檔。</p><div class="actions">${btn('close', '取消', false, 'ghost')}${btn('resetok', '全部清除', false, 'danger')}</div>`);
      return;
    case 'resetok': emit('before-reset'); S = defaultState(); TAB = 'today'; save('reset'); closeModal(); emit('reset'); return;
    case 'newsem': {
      openModal(`<h2>開始新學期？</h2><p>請先確認「設定」裡的學期開始日、週數、課表與假日已更新成新學期的內容（目前：${D.md(S.settings.semStart)} 起 ${S.settings.weeks} 週）。等級、羈絆、技能、道具、紀念冊與徽章都會保留。</p>
        <div class="actions">${btn('tab:settings', '先去設定', false, 'ghost')}${btn('newsemok', '開始新學期', false, 'primary')}</div>`);
      return;
    }
    case 'newsemok': {
      if (semEnd() < today()) { closeModal(); TAB = 'settings'; render(); toast('學期日期還是舊的，請先更新學期開始日'); return; }
      S.history.push(S.ending);
      S.ending = null;
      const start = today() < S.settings.semStart ? S.settings.semStart : today();
      S.createdAt = start;
      S.settledThrough = D.add(start, -1);
      S.streak.attend = 0; S.streak.bad = 0; S.streak.prevAbsent = false;
      logEv('新學期開始', start);
      save('newsem'); closeModal(); TAB = 'today'; render(); emit('newsem'); return;
    }
    default:
  }
}

function collectSchedule() {
  let ok = true;
  const weak = [];
  document.querySelectorAll('tr[data-row]').forEach((tr) => {
    const id = tr.dataset.row;
    const s = S.schedule.find((x) => x.id === id);
    if (!s) return;
    const g = (f) => tr.querySelector(`[data-f="${f}"]`);
    const name = g('name').value.trim();
    const start = g('start').value, end = g('end').value;
    if (name && name !== s.name) { s.name = name; delete s.short; }
    s.day = Number(g('day').value);
    if (start && end && tmin(end) > tmin(start)) { s.start = start; s.end = end; } else ok = false;
    s.room = g('room').value.trim();
    s.diff = Number(g('diff').value);
    s.guardian = g('guardian').value;
    s.parity = g('parity').value;
    s.from = g('from').value || '';
    s.to = g('to').value || '';
    if (g('weak').checked) weak.push(id);
  });
  if (document.querySelector('tr[data-row]')) S.settings.weakIds = weak;
  return ok;
}

function collectSisSchedule() {
  let ok = true;
  document.querySelectorAll('tr[data-srow]').forEach((tr) => {
    const g0 = S.sisSchedule.find((x) => x.id === tr.dataset.srow);
    if (!g0) return;
    const g = (f) => tr.querySelector(`[data-g="${f}"]`);
    const name = g('name').value.trim();
    if (name && name !== g0.name) { g0.name = name; delete g0.short; }
    g0.icon = g('icon').value.trim();
    g0.day = Number(g('day').value);
    const start = g('start').value, end = g('end').value;
    if (start && end && tmin(end) > tmin(start)) { g0.start = start; g0.end = end; } else ok = false;
    g0.room = g('room').value.trim();
  });
  return ok;
}

async function exportSave() {
  // 雲端擴充：匯出前把雲端照片補回 data URL，維持與單檔版相同的 JSON 格式
  let data = S;
  if (HOOKS.exportState) { try { data = await HOOKS.exportState(S); } catch (e) { console.warn('[cloud] exportState failed', e); data = S; } }
  const blob = new Blob([JSON.stringify(data, null, 1)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `晨光羈絆存檔-${today()}.json`;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);
  toast('已匯出存檔');
}

function importSave(file) {
  const fr = new FileReader();
  fr.onload = () => {
    try {
      const data = JSON.parse(fr.result);
      if (!data || typeof data !== 'object' || !data.settings || !data.player) throw new Error('格式不符');
      emit('before-import');
      S = migrate(data);
      save('import'); TAB = 'today'; render(); toast('已匯入存檔');
      emit('import');
    } catch (e) { toast('匯入失敗：檔案格式不正確'); }
  };
  fr.readAsText(file);
}

function loadPhoto(who, file) {
  const fr = new FileReader();
  fr.onload = () => {
    const img = new Image();
    img.onload = () => {
      const size = 256, c = document.createElement('canvas');
      c.width = size; c.height = Math.round(size * 1.2);
      const ctx = c.getContext('2d');
      const r = Math.max(c.width / img.width, c.height / img.height);
      const w = img.width * r, h = img.height * r;
      ctx.drawImage(img, (c.width - w) / 2, (c.height - h) / 2, w, h);
      S.profile.photos[who] = c.toDataURL('image/jpeg', 0.85);
      S.profile.usePhotos = true;
      save('photo'); render(); toast('已更新照片');
      emit('photo', { who });
    };
    img.onerror = () => toast('這個檔案無法讀取成圖片');
    img.src = fr.result;
  };
  fr.readAsDataURL(file);
}

// 晨間叮嚀語音（瀏覽器內建語音合成；找不到中文語音就不唸）
function speakLine(text) {
  if (!S.profile.voice) return;
  try {
    const synth = window.speechSynthesis;
    if (!synth) return;
    const voices = synth.getVoices();
    const v = voices.find((x) => /zh[-_](TW|Hant)/i.test(x.lang)) || voices.find((x) => /^zh/i.test(x.lang)) || voices.find((x) => /^cmn/i.test(x.lang));
    if (!v) return;
    const u = new SpeechSynthesisUtterance(text);
    u.voice = v; u.lang = v.lang; u.rate = 0.95; u.pitch = 1.1;
    synth.cancel();
    synth.speak(u);
  } catch (e) { /* 不支援語音就略過 */ }
}

// =====================================================================
//  啟動
// =====================================================================

function init() {
  initToon();
  load();
  document.addEventListener('click', (e) => {
    const el = e.target.closest('[data-act]');
    if (!el || el.disabled) return;
    if (el.tagName === 'A') e.preventDefault();
    const [act, ...args] = el.dataset.act.split(':');
    try { handle(act, args, el); } catch (err) { console.error(err); toast('發生錯誤：' + err.message); }
  });
  document.addEventListener('change', (e) => {
    const el = e.target;
    if (el.dataset.bind === 'bedtime') {
      const d = playDate();
      if (d && S.days[d]) { S.days[d].bedtime = el.value || S.settings.bedtime; save(); }
    } else if (el.dataset.bind === 'usePhotos') {
      S.profile.usePhotos = el.checked; save(); render();
    } else if (el.dataset.bind === 'avatarStyle') {
      S.profile.avatarStyle = el.value === 'svg' ? 'svg' : 'toon'; save(); render();
    } else if (el.dataset.bind === 'sibDate') {
      if (isDate(el.value)) { UI.sibDate = el.value; render(); }
    } else if (el.dataset.bind === 'voice') {
      S.profile.voice = el.checked; save();
      if (el.checked) speakLine('早安，今天也要好好吃早餐喔。');
    } else if (el.dataset.photo && el.files && el.files[0]) {
      loadPhoto(el.dataset.photo, el.files[0]);
    } else if (el.dataset.import && el.files && el.files[0]) {
      importSave(el.files[0]);
    }
  });
  document.addEventListener('keydown', (e) => {
    if (!modalOpen) return;
    if (UI.story && (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowRight')) {
      e.preventDefault();
      handle('storynext', []);
    } else if (e.key === 'Escape' && !UI.story && !(UI.event && UI.event.chosen == null)) {
      closeModal();
    }
  });
  document.getElementById('modal').addEventListener('click', (e) => {
    if (e.target.id === 'modal' && !UI.story && !(UI.event && UI.event.chosen == null)) closeModal();
  });
  let lastDay = today();
  setInterval(() => {
    if (today() !== lastDay) { lastDay = today(); if (!modalOpen) render(); return; }
    // 兄妹分頁：每分鐘更新妹妹的即時狀態（正在輸入時不打擾）
    const ae = document.activeElement;
    const typing = ae && /INPUT|SELECT|TEXTAREA/.test(ae.tagName);
    if (TAB === 'sib' && !modalOpen && !typing) render();
  }, 60000);
  try { if (window.speechSynthesis) window.speechSynthesis.getVoices(); } catch (e) { /* 略過 */ }
  render();
  flushQueue();
}

// 測試與除錯用（不影響遊玩）
window.__cg = {
  get state() { return S; }, pickEvent, today, playDate, computeDay, settleDay, skipDay, render, handle, sessionsOn,
  holidayBlocks, knowValue, knowTarget, sisSessionsOn, sisStatus, migrate, defaultState, attendanceStats, endingType, closeModal, flushQueue, beginDay, getDay, holidayStatus, weekStatus,
  get modalOpen() { return modalOpen; },
};


// =====================================================================
//  對外介面（給 main.js / save-manager.js / cloud-ui.js 使用）
// =====================================================================
function setHooks(h) { Object.assign(HOOKS, h || {}); }
function getState() { return S; }
// 以另一份完整存檔取代目前進度（雲端讀取、衝突處理、還原備份時使用）。會先跑原本的 migrate()。
function replaceState(next, opts = {}) {
  S = migrate(JSON.parse(JSON.stringify(next)));
  MEMO = { key: '', set: null, blocks: null };
  UI.interWho = null; UI.story = null; UI.event = null; UI.sibDate = null;
  if (modalOpen) closeModal();
  save(opts.reason || 'replace');
  if (opts.render !== false) { if (!S.started) TAB = 'today'; render(); flushQueue(); }
  return S;
}
function readLocalRaw() { try { return localStorage.getItem(SAVE_KEY); } catch (e) { return null; } }
const isModalOpen = () => modalOpen;

export {
  init, setHooks, getState, replaceState, render, save, load, migrate, defaultState, toast, today,
  SAVE_KEY, readLocalRaw, isModalOpen, LEVELS, nameOf, MEMBER, closeModal, flushQueue,
};
